export type HistoryQuestion = {
  id: string;
  prompt: string;
  year: number;
  min: number;
  max: number;
  difficulty: 'core' | 'survey' | 'specialist';
  detail: string;
  source: string;
  sourceUrl: string;
  verifiedAt: string;
};

export const historyQuestionTarget = 1000;
export const dailyHistoryQuestionCount = 10;

export const historyQuestions: HistoryQuestion[] = [
  { id: 'djoser-step-pyramid', prompt: 'Around when was Djoser’s Step Pyramid built?', year: -2780, min: -3200, max: -2300, difficulty: 'survey', detail: 'The Smithsonian dates the project to around 2780 BCE and identifies Imhotep as its architect. The exact chronology of Egypt’s Third Dynasty remains approximate.', source: 'Smithsonian Institution — The Egyptian Pyramid', sourceUrl: 'https://www.si.edu/spotlight/ancient-egypt/pyramid', verifiedAt: '2026-08-31' },
  { id: 'code-of-hammurabi', prompt: 'Around when was Hammurabi’s law code carved?', year: -1750, min: -2200, max: -1300, difficulty: 'survey', detail: 'The Louvre dates the surviving stela to Hammurabi’s reign, 1792–1750 BCE. This game uses 1750 BCE as a memorable approximate anchor, not a precise day.', source: 'Musée du Louvre — Code of Hammurabi', sourceUrl: 'https://collections.louvre.fr/en/ark:/53355/cl010174436', verifiedAt: '2026-08-31' },
  { id: 'olmec-florescence', prompt: 'Around when did the Olmec cultural florescence begin?', year: -1200, min: -1600, max: -700, difficulty: 'survey', detail: 'The Met dates the major Olmec cultural and artistic florescence on Mexico’s Gulf Coast to roughly 1200–400 BCE. “Olmec” groups were not a single unified empire.', source: 'Metropolitan Museum of Art — Olmec Art', sourceUrl: 'https://www.metmuseum.org/es/essays/olmec-art', verifiedAt: '2026-08-31' },
  { id: 'achaemenid-empire', prompt: 'Around when did the Achaemenid Persian Empire begin?', year: -550, min: -800, max: -300, difficulty: 'core', detail: 'The Achaemenid Empire is conventionally dated from about 550 BCE, when Cyrus II overthrew the Median king and began a rapid imperial expansion.', source: 'Metropolitan Museum of Art — Achaemenid Persian Empire', sourceUrl: 'https://www.metmuseum.org/ja/essays/the-achaemenid-persian-empire-550-330-b-c', verifiedAt: '2026-08-31' },
  { id: 'mauryan-empire', prompt: 'Around when did the Mauryan Empire begin?', year: -321, min: -550, max: -100, difficulty: 'survey', detail: 'The Mauryan dynasty emerged around 321 BCE and built the first empire to unite most of the Indian subcontinent. Its boundaries changed over time.', source: 'Metropolitan Museum of Art — The Year One', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Year_One_Art_of_the_Ancient_World_East_and_West.pdf', verifiedAt: '2026-08-31' },
  { id: 'teotihuacan-established', prompt: 'Around when was Teotihuacan established?', year: -150, min: -400, max: 100, difficulty: 'specialist', detail: 'The Met’s chronology places Teotihuacan’s establishment around 150 BCE. The settlement expanded over generations rather than appearing as a finished city in one year.', source: 'Metropolitan Museum of Art — Mexico, 1000 BCE–1 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/04/cam.html', verifiedAt: '2026-08-31' },
  { id: 'teotihuacan-city-grid', prompt: 'Around when was Teotihuacan’s city grid established?', year: 50, min: -150, max: 300, difficulty: 'specialist', detail: 'The Met dates establishment of Teotihuacan’s grid and early monumental construction along the Street of the Dead to around 50 CE.', source: 'Metropolitan Museum of Art — Mexico, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/cam.html', verifiedAt: '2026-08-31' },
  { id: 'classic-maya-city-states', prompt: 'Around when did Classic Maya dynastic city-states emerge?', year: 250, min: 1, max: 600, difficulty: 'survey', detail: 'The conventional Classic Maya period begins around 250 CE, when dynastic city-states and their characteristic monuments became prominent. Period boundaries are scholarly tools.', source: 'Metropolitan Museum of Art — Maya Area, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/caa.html', verifiedAt: '2026-08-31' },
  { id: 'aksumite-coinage', prompt: 'Around when did the kingdom of Aksum begin issuing coins?', year: 270, min: 1, max: 600, difficulty: 'specialist', detail: 'Aksum began minting its own coinage around the late third century CE. The exact opening date is approximate, so the game uses 270 CE as a rough anchor.', source: 'Metropolitan Museum of Art — Foundations of Aksumite Civilization', sourceUrl: 'https://www.metmuseum.org/ja/essays/foundations-of-aksumite-civilization-and-its-christian-legacy-1st-7th-century', verifiedAt: '2026-08-31' },
  { id: 'gupta-dynasty', prompt: 'Around when did the Gupta dynasty begin?', year: 320, min: 100, max: 600, difficulty: 'survey', detail: 'The Gupta era is conventionally dated from around 320 CE. Its political reach and the “golden age” label both require regional and cultural qualification.', source: 'Smarthistory — The Gupta Period', sourceUrl: 'https://smarthistory.org/gupta-period/', verifiedAt: '2026-08-31' },
  { id: 'teotihuacan-tikal', prompt: 'When did a Teotihuacan-linked force arrive at Tikal?', year: 378, min: 150, max: 600, difficulty: 'specialist', detail: 'Maya inscriptions record the arrival of a figure linked to Teotihuacan at Tikal in 378 CE, followed by a new ruler with strong central Mexican ties.', source: 'Metropolitan Museum of Art — Maya Area, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/caa.html', verifiedAt: '2026-08-31' },
  { id: 'palenque-dynasty', prompt: 'When did Palenque’s recorded dynasty begin?', year: 431, min: 200, max: 700, difficulty: 'specialist', detail: 'Palenque’s inscriptions date the accession of its first recorded dynastic ruler, K’uk’ Balam I, to 431 CE. Earlier settlement at the site is not ruled out.', source: 'Metropolitan Museum of Art — Maya Area, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/caa.html', verifiedAt: '2026-08-31' },
  { id: 'olympic-chronology', prompt: 'When does the reliable ancient Olympic chronology begin?', year: -776, min: -1100, max: -500, difficulty: 'specialist', detail: 'The conventional reliable list begins with the victor Koroibos in 776 BCE. Games and legends existed earlier, so this is not a claim that Olympic competition began that year.', source: 'Journal of Olympic History — Ancient Olympic Apocrypha', sourceUrl: 'https://library.olympics.com/digitalCollection/DigitalCollectionAttachmentDownloadHandler.ashx?documentId=2435425&parentDocumentId=2435424&skipCopyright=true&skipWatermark=true', verifiedAt: '2026-08-31' },
  { id: 'battle-of-marathon', prompt: 'When was the Battle of Marathon?', year: -490, min: -700, max: -300, difficulty: 'core', detail: 'Athenians and Plataeans defeated a Persian invasion force at Marathon in 490 BCE during the Greco-Persian Wars.', source: 'Encyclopaedia Britannica — Battle of Marathon', sourceUrl: 'https://www.britannica.com/event/Battle-of-Marathon', verifiedAt: '2026-08-31' },
  { id: 'alexander-death', prompt: 'When did Alexander the Great die?', year: -323, min: -500, max: -100, difficulty: 'core', detail: 'Alexander died unexpectedly in Babylon in June 323 BCE. His generals then fought over and divided the empire.', source: 'Metropolitan Museum of Art — The Hellenistic Age', sourceUrl: 'https://www.metmuseum.org/essays/art-of-the-hellenistic-age-and-the-hellenistic-tradition', verifiedAt: '2026-08-31' },
  { id: 'qin-unification', prompt: 'When did Qin unify China?', year: -221, min: -450, max: -50, difficulty: 'survey', detail: 'Ying Zheng conquered the remaining rival states and proclaimed himself First Emperor in 221 BCE. The Qin dynasty itself was short-lived.', source: 'Metropolitan Museum of Art — Age of Empires', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2017/age-of-empires/exhibition-galleries', verifiedAt: '2026-08-31' },
  { id: 'augustus-title', prompt: 'When did Octavian receive the title Augustus?', year: -27, min: -150, max: 100, difficulty: 'survey', detail: 'The Roman Senate awarded Octavian the title Augustus in 27 BCE, the conventional beginning of the Roman imperial principate.', source: 'Metropolitan Museum of Art — The Roman Empire', sourceUrl: 'https://www.metmuseum.org/essays/the-roman-empire-27-b-c-393-a-d', verifiedAt: '2026-08-31' },
  { id: 'vesuvius-pompeii', prompt: 'When did Vesuvius bury Pompeii and Herculaneum?', year: 79, min: -100, max: 300, difficulty: 'core', detail: 'Mount Vesuvius erupted in 79 CE, burying Pompeii, Herculaneum, and nearby settlements and preserving an exceptional record of Roman life.', source: 'Metropolitan Museum of Art — Roman Art', sourceUrl: 'https://www.metmuseum.org/met-publications/roman-art-a-resource-for-educators', verifiedAt: '2026-08-31' },
  { id: 'constantinople-capital', prompt: 'When did Constantine establish Constantinople as New Rome?', year: 330, min: 150, max: 550, difficulty: 'survey', detail: 'Constantine dedicated Constantinople in 330 CE and shifted the imperial center eastward. Rome remained central to the western church.', source: 'Metropolitan Museum of Art — Italian Peninsula, 1–500 CE', sourceUrl: 'https://www.metmuseum.org/toah/ht/05/eust.html', verifiedAt: '2026-08-31' },
  { id: 'western-rome-end', prompt: 'When was the last western Roman emperor deposed?', year: 476, min: 250, max: 700, difficulty: 'core', detail: 'Odovacer deposed Romulus Augustulus in 476 CE, the conventional endpoint of the Western Roman Empire. The Eastern Roman Empire continued for centuries.', source: 'Metropolitan Museum of Art — The Roman Empire', sourceUrl: 'https://www.metmuseum.org/essays/the-roman-empire-27-b-c-393-a-d', verifiedAt: '2026-08-31' },
  { id: 'tang-dynasty', prompt: 'When did the Tang dynasty begin in China?', year: 618, min: 450, max: 850, difficulty: 'survey', detail: 'Li Yuan founded the Tang dynasty in 618 CE. Tang rule lasted, with an interruption, until 907 and presided over a major era of trade and cultural exchange.', source: 'Metropolitan Museum of Art — Central and North Asia, 500–1000', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/06/nc.html', verifiedAt: '2026-08-31' },
  { id: 'hijra', prompt: 'When did Muhammad and his followers migrate to Medina?', year: 622, min: 450, max: 850, difficulty: 'core', detail: 'The Hijra from Mecca to Medina occurred in 622 CE. It marks the starting point of the Islamic calendar, not the beginning of Muhammad’s prophetic career.', source: 'Metropolitan Museum of Art — The Birth of Islam', sourceUrl: 'https://www.metmuseum.org/essays/the-birth-of-islam', verifiedAt: '2026-08-31' },
  { id: 'baghdad-founded', prompt: 'When did the Abbasids found Baghdad?', year: 762, min: 550, max: 1000, difficulty: 'survey', detail: 'The Abbasid caliph al-Mansur founded Baghdad as his new capital in 762 CE. The city became a major political, commercial, and intellectual center.', source: 'Metropolitan Museum of Art — Central and North Asia, 500–1000', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/06/nc.html', verifiedAt: '2026-08-31' },
  { id: 'charlemagne-emperor', prompt: 'When was Charlemagne crowned emperor in Rome?', year: 800, min: 600, max: 1050, difficulty: 'core', detail: 'Pope Leo III crowned Charlemagne emperor in Rome on Christmas Day in 800 CE. The title shaped later claims to imperial authority in western Europe.', source: 'Metropolitan Museum of Art — Carolingian Art', sourceUrl: 'https://www.metmuseum.org/essays/carolingian-art', verifiedAt: '2026-08-31' },
  { id: 'norman-conquest', prompt: 'When did the Norman Conquest of England begin?', year: 1066, min: 850, max: 1250, difficulty: 'core', detail: 'William of Normandy invaded England and defeated Harold at Hastings in 1066. Conquest and consolidation continued after the battle.', source: 'UK Parliament — The Palace and the Normans', sourceUrl: 'https://www.parliament.uk/about/living-heritage/building/palace/estatehistory/the-middle-ages/palace-normans/', verifiedAt: '2026-08-31' },
  { id: 'first-crusade', prompt: 'When did Pope Urban II call the First Crusade?', year: 1095, min: 850, max: 1300, difficulty: 'survey', detail: 'Urban II called for an armed pilgrimage at the Council of Clermont in 1095. Crusading armies reached and captured Jerusalem in 1099.', source: 'Metropolitan Museum of Art — The Crusades', sourceUrl: 'https://www.metmuseum.org/toah/hd/crus/hd_crus.htm', verifiedAt: '2026-08-31' },
  { id: 'genghis-khan-proclaimed', prompt: 'When was Temüjin proclaimed Genghis Khan?', year: 1206, min: 950, max: 1400, difficulty: 'survey', detail: 'A great assembly recognized Temüjin as Genghis Khan in 1206, conventionally marking the foundation of the Mongol Empire.', source: 'Metropolitan Museum of Art — The Legacy of Genghis Khan', sourceUrl: 'https://www.metmuseum.org/essays/the-legacy-of-genghis-khan', verifiedAt: '2026-08-31' },
  { id: 'mali-empire-rise', prompt: 'Around when did the Mali Empire emerge?', year: 1235, min: 950, max: 1500, difficulty: 'specialist', detail: 'Mali’s rise is conventionally associated with Sundiata’s victory around 1235. The date is approximate and partly reconstructed from oral traditions.', source: 'Metropolitan Museum of Art — Empires of the Western Sudan', sourceUrl: 'https://www.metmuseum.org/essays/the-empires-of-the-western-sudan', verifiedAt: '2026-08-31' },
  { id: 'black-death-europe', prompt: 'When did the Black Death reach Europe?', year: 1347, min: 1150, max: 1550, difficulty: 'core', detail: 'The pandemic reached Mediterranean Europe in 1347 and spread widely through 1351. Outbreaks and demographic effects varied across regions.', source: 'Metropolitan Museum of Art — The Art of Renaissance Europe', sourceUrl: 'https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf', verifiedAt: '2026-08-31' },
  { id: 'fall-of-constantinople', prompt: 'When did the Ottomans capture Constantinople?', year: 1453, min: 1250, max: 1650, difficulty: 'core', detail: 'Mehmed II’s Ottoman army captured Constantinople in May 1453, ending the Byzantine Empire. Trebizond remained independent until 1461.', source: 'Metropolitan Museum of Art — The Art of Renaissance Europe', sourceUrl: 'https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf', verifiedAt: '2026-08-31' },
  { id: 'magna-carta', prompt: 'When was Magna Carta first issued?', year: 1215, min: 1000, max: 1500, difficulty: 'core', detail: 'King John authorized the first Magna Carta at Runnymede in June 1215. Later reissues changed its text and legacy.', source: 'UK Parliament — Magna Carta', sourceUrl: 'https://www.parliament.uk/about/living-heritage/evolutionofparliament/originsofparliament/birthofparliament/overview/magnacarta/', verifiedAt: '2026-08-31' },
  { id: 'ming-dynasty', prompt: 'When did Zhu Yuanzhang establish the Ming dynasty?', year: 1368, min: 1150, max: 1550, difficulty: 'survey', detail: 'Zhu Yuanzhang emerged victorious in 1368, expelled the Yuan court, and ruled as the Hongwu emperor.', source: 'Metropolitan Museum of Art — The Yuan Revolution', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2010/yuan-revolution', verifiedAt: '2026-08-31' },
  { id: 'gutenberg-printing', prompt: 'Around when did Gutenberg-era movable-type printing begin in Europe?', year: 1450, min: 1250, max: 1650, difficulty: 'core', detail: 'The date is approximate: historians place the beginning of European typography around 1450, before the Gutenberg Bible was completed.', source: 'Library of Congress — Gutenberg resources', sourceUrl: 'https://guides.loc.gov/gutenberg/resources', verifiedAt: '2026-08-31' },
  { id: 'columbus-caribbean', prompt: 'When did Columbus first reach the Caribbean?', year: 1492, min: 1300, max: 1700, difficulty: 'core', detail: 'Columbus reached the Bahamian island Guanahaní on 12 October 1492, beginning a new phase of European conquest and colonization.', source: 'Library of Congress — Columbus and the Taíno', sourceUrl: 'https://www.loc.gov/exhibits/exploring-the-early-americas/columbus-and-the-taino.html', verifiedAt: '2026-08-31' },
  { id: 'qing-dynasty', prompt: 'When did the Manchus establish Qing rule in China?', year: 1644, min: 1450, max: 1800, difficulty: 'survey', detail: 'The Manchus entered Beijing and established Qing rule in 1644; conquest and consolidation continued for decades.', source: 'Metropolitan Museum of Art — The Qing Dynasty', sourceUrl: 'https://www.metmuseum.org/essays/the-qing-dynasty-1644-1911-painting', verifiedAt: '2026-08-31' },
  { id: 'spinning-jenny', prompt: 'When did James Hargreaves invent the spinning jenny?', year: 1764, min: 1600, max: 1900, difficulty: 'survey', detail: 'Hargreaves is generally credited with inventing the multi-spindle spinning jenny around 1764; he patented a later version in 1770.', source: 'Encyclopaedia Britannica — Spinning jenny', sourceUrl: 'https://www.britannica.com/technology/spinning-jenny', verifiedAt: '2026-08-31' },
  { id: 'watt-patent', prompt: 'When was Watt’s separate-condenser patent granted?', year: 1769, min: 1600, max: 1900, difficulty: 'survey', detail: 'Watt conceived the separate condenser earlier, but this question asks for the patent granted on 5 January 1769.', source: 'Science Museum — James Watt and the separate condenser', sourceUrl: 'https://blog.sciencemuseum.org.uk/james-watt-and-the-separate-condenser/', verifiedAt: '2026-08-31' },
  { id: 'french-revolution', prompt: 'When did the French Revolution begin?', year: 1789, min: 1650, max: 1950, difficulty: 'core', detail: 'This uses 1789, the year of the Estates-General, the National Assembly, and the storming of the Bastille, as the conventional start.', source: 'U.S. National Archives — Onset of the French Revolution', sourceUrl: 'https://www.archives.gov/exhibits/eyewitness/html.php?section=1', verifiedAt: '2026-08-31' },
  { id: 'haitian-independence', prompt: 'When did Haiti declare independence from France?', year: 1804, min: 1650, max: 1950, difficulty: 'survey', detail: 'Haitian generals signed the declaration on 1 January 1804 after a thirteen-year revolution against slavery and colonial rule.', source: 'Library of Congress — Ayiti Reimagined', sourceUrl: 'https://guides.loc.gov/haiti-reimagined', verifiedAt: '2026-08-31' },
  { id: 'telegraph', prompt: 'When was a practical electric telegraph first demonstrated in Britain?', year: 1837, min: 1700, max: 2000, difficulty: 'specialist', detail: 'Cooke and Wheatstone demonstrated their five-needle electric telegraph to railway directors in 1837.', source: 'Science Museum — Cooke and Wheatstone telegraph', sourceUrl: 'https://blog.sciencemuseum.org.uk/revealing-the-real-cooke-and-wheatstone-telegraph-dial/', verifiedAt: '2026-08-31' },
  { id: 'meiji-restoration', prompt: 'When did the Meiji Restoration change Japan’s regime?', year: 1868, min: 1700, max: 2000, difficulty: 'survey', detail: 'Imperial rule was proclaimed in January 1868, beginning the new Meiji government and a far-reaching transformation of Japan.', source: 'National Diet Library of Japan — Meiji government', sourceUrl: 'https://www.ndl.go.jp/portrait/e/pickup/012/', verifiedAt: '2026-08-31' },
  { id: 'indian-independence', prompt: 'When did British rule end in India?', year: 1947, min: 1800, max: 2020, difficulty: 'core', detail: 'British India was partitioned into India and Pakistan in August 1947; independence and partition unfolded together.', source: 'UK National Archives — Indian Independence', sourceUrl: 'https://www.nationalarchives.gov.uk/education/resources/indian-independence/', verifiedAt: '2026-08-31' },
  { id: 'berlin-wall-fall', prompt: 'When did the Berlin Wall fall?', year: 1989, min: 1900, max: 2020, difficulty: 'core', detail: 'East Germany opened the border on 9 November 1989. Formal German reunification followed in October 1990.', source: 'German Bundestag — 1989–1990', sourceUrl: 'https://www.bundestag.de/resource/blob/480634/exhibition_dome.pdf', verifiedAt: '2026-08-31' },
  { id: 'stockton-darlington-railway', prompt: 'When did the first steam-hauled passenger train run on a public railway?', year: 1825, min: 1650, max: 2000, difficulty: 'specialist', detail: 'On 27 September 1825, Locomotion No. 1 hauled a passenger train on the Stockton and Darlington Railway, the first steam-hauled passenger public railway.', source: 'National Railway Museum — Shildon and Locomotion No. 1', sourceUrl: 'https://blog.railwaymuseum.org.uk/shildon-the-cradle-of-the-railways-and-locomotion-no-1/', verifiedAt: '2026-08-31' },
  { id: 'mendeleev-periodic-table', prompt: 'When did Mendeleev devise his periodic table?', year: 1869, min: 1700, max: 2000, difficulty: 'survey', detail: 'Dmitri Mendeleev devised his periodic system in February 1869 while arranging the known elements by atomic weight and recurring chemical properties.', source: 'Royal Society of Chemistry — Development of the periodic table', sourceUrl: 'https://periodic-table.rsc.org/about', verifiedAt: '2026-08-31' },
  { id: 'wright-first-flight', prompt: 'When did the Wright brothers make the first successful powered airplane flight?', year: 1903, min: 1750, max: 2020, difficulty: 'core', detail: 'Orville Wright piloted the first of four successful powered flights at Kitty Hawk on 17 December 1903; the opening flight lasted twelve seconds.', source: 'Smithsonian National Air and Space Museum — 1903 Wright Flyer', sourceUrl: 'https://airandspace.si.edu/collection-objects/1903-wright-flyer/nasm_A19610048000', verifiedAt: '2026-08-31' },
  { id: 'fleming-penicillin', prompt: 'When did Alexander Fleming discover penicillin?', year: 1928, min: 1800, max: 2020, difficulty: 'core', detail: 'Fleming observed in 1928 that a Penicillium mould inhibited bacterial growth. He published the finding in 1929; later teams made penicillin a practical drug.', source: 'Nobel Prize — Alexander Fleming questions and answers', sourceUrl: 'https://www.nobelprize.org/prizes/medicine/1945/fleming/questions-and-answers/', verifiedAt: '2026-08-31' },
  { id: 'dna-double-helix', prompt: 'When was the double-helix structure of DNA determined?', year: 1953, min: 1800, max: 2020, difficulty: 'core', detail: 'Watson and Crick determined the double-helix structure in 1953, building on essential experimental work by Rosalind Franklin, Maurice Wilkins, and others.', source: 'Nobel Prize — Exploring life’s smallest details', sourceUrl: 'https://www.nobelprize.org/stories/cells-nerves-genes/', verifiedAt: '2026-08-31' },
  { id: 'sputnik-1', prompt: 'When did the Soviet Union launch Sputnik 1?', year: 1957, min: 1850, max: 2020, difficulty: 'survey', detail: 'The Soviet Union launched Sputnik 1 on 4 October 1957. It was the first artificial satellite and marked the conventional opening of the Space Age.', source: 'NASA — Dawn of the Space Age', sourceUrl: 'https://www.nasa.gov/history/dawn-of-the-space-age/', verifiedAt: '2026-08-31' },
  { id: 'apollo-11-moon-landing', prompt: 'When did humans first land on the Moon?', year: 1969, min: 1850, max: 2020, difficulty: 'core', detail: 'Apollo 11 landed on 20 July 1969. Neil Armstrong and Buzz Aldrin walked on the lunar surface while Michael Collins remained in lunar orbit.', source: 'NASA — Apollo 11 Mission Overview', sourceUrl: 'https://www.nasa.gov/missions/apollo/apollo-11/apollo-11-mission-overview/', verifiedAt: '2026-08-31' },
  { id: 'smallpox-eradication', prompt: 'When did the World Health Assembly declare smallpox eradicated?', year: 1980, min: 1850, max: 2020, difficulty: 'survey', detail: 'The World Health Assembly officially declared smallpox eradicated in May 1980 after an international vaccination and surveillance campaign.', source: 'World Health Organization — History of smallpox vaccination', sourceUrl: 'https://www.who.int/news-room/spotlight/history-of-vaccination/history-of-smallpox-vaccination', verifiedAt: '2026-08-31' },
  { id: 'human-genome-project-complete', prompt: 'When was the Human Genome Project declared complete?', year: 2003, min: 1900, max: 2020, difficulty: 'survey', detail: 'The international consortium announced completion on 14 April 2003. Its sequence covered about 92% of the genome; a gapless sequence came later.', source: 'National Human Genome Research Institute — Human Genome Project Timeline', sourceUrl: 'https://www.genome.gov/human-genome-project/timeline', verifiedAt: '2026-08-31' },
  { id: 'crispr-cas9-genome-editing', prompt: 'When was CRISPR-Cas9 demonstrated as a programmable genome-editing tool?', year: 2012, min: 1900, max: 2020, difficulty: 'specialist', detail: 'Emmanuelle Charpentier and Jennifer Doudna reported programmable CRISPR-Cas9 genetic scissors in 2012, enabling targeted changes to DNA.', source: 'Nobel Prize — Chemistry 2020 press release', sourceUrl: 'https://www.nobelprize.org/prizes/chemistry/2020/press-release/', verifiedAt: '2026-08-31' },
  { id: 'jenner-smallpox-vaccination', prompt: 'When did Edward Jenner perform his famous smallpox vaccination experiment?', year: 1796, min: 1600, max: 1950, difficulty: 'core', detail: 'Jenner inoculated James Phipps with material from a cowpox lesion in May 1796, then tested whether it protected him from smallpox. Variolation traditions predated this experiment.', source: 'U.S. National Library of Medicine — Smallpox vaccination', sourceUrl: 'https://www.nlm.nih.gov/exhibition/smallpox/sp_vaccination.html', verifiedAt: '2026-08-31' },
  { id: 'ether-anesthesia-demonstration', prompt: 'When was ether anesthesia first demonstrated publicly in surgery?', year: 1846, min: 1700, max: 2000, difficulty: 'survey', detail: 'William T. G. Morton publicly demonstrated ether anesthesia during surgery at Massachusetts General Hospital on 16 October 1846. Earlier practitioners had used ether without this public demonstration.', source: 'Massachusetts General Hospital — 200 years of patient care', sourceUrl: 'https://www.massgeneral.org/news/press-release/massachusetts-general-hospital-marks-200-years-of-patient-care', verifiedAt: '2026-08-31' },
  { id: 'lister-antiseptic-surgery', prompt: 'When did Joseph Lister publish his antiseptic surgical method?', year: 1867, min: 1750, max: 2000, difficulty: 'survey', detail: 'Lister published a series of reports on carbolic-acid treatment of surgical wounds in 1867. The method evolved, and modern aseptic practice differs from his original technique.', source: 'PubMed Central — On the Antiseptic Principle in the Practice of Surgery', sourceUrl: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2895849/', verifiedAt: '2026-08-31' },
  { id: 'roentgen-x-rays', prompt: 'When did Wilhelm Röntgen discover X-rays?', year: 1895, min: 1750, max: 2020, difficulty: 'core', detail: 'Röntgen observed the new radiation in November 1895 and submitted his first paper in December. Diagnostic applications spread rapidly during the following year.', source: 'PubMed — Early history of X-ray diagnosis', sourceUrl: 'https://pubmed.ncbi.nlm.nih.gov/8587931/', verifiedAt: '2026-08-31' },
  { id: 'insulin-discovery', prompt: 'When did the Toronto team begin the experiments that led to insulin therapy?', year: 1921, min: 1800, max: 2020, difficulty: 'survey', detail: 'Frederick Banting and Charles Best began their pancreatic-extract experiments in 1921 under John Macleod. James Collip later helped purify insulin for human treatment.', source: 'Nobel Prize — The discovery of insulin', sourceUrl: 'https://educationalgames.nobelprize.org/educational/medicine/insulin/discovery-insulin.html', verifiedAt: '2026-08-31' },
  { id: 'salk-polio-vaccine', prompt: 'When was the first effective Salk polio vaccine announced?', year: 1955, min: 1850, max: 2020, difficulty: 'core', detail: 'Results announced on 12 April 1955 showed that the inactivated vaccine developed by Jonas Salk and his team was effective. A manufacturing failure soon prompted stronger oversight.', source: 'CDC — 50th anniversary of the first effective polio vaccine', sourceUrl: 'https://www.cdc.gov/mmwr/preview/mmwrhtml/mm5413a5.htm', verifiedAt: '2026-08-31' },
  { id: 'first-human-heart-transplant', prompt: 'When was the first human-to-human heart transplant performed?', year: 1967, min: 1900, max: 2020, difficulty: 'core', detail: 'Christiaan Barnard and his team performed the operation in Cape Town on 3 December 1967. Recipient Louis Washkansky survived eighteen days before dying of pneumonia.', source: 'PubMed Central — First human heart transplant', sourceUrl: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4200566/', verifiedAt: '2026-08-31' },
  { id: 'first-ivf-birth', prompt: 'When was the first child conceived through IVF born?', year: 1978, min: 1900, max: 2020, difficulty: 'core', detail: 'Louise Brown was born on 25 July 1978 after IVF work by Robert Edwards, Patrick Steptoe, and Jean Purdy. The milestone established IVF as a viable clinical treatment.', source: 'Nobel Prize — Physiology or Medicine 2010 press release', sourceUrl: 'https://www.nobelprize.org/prizes/medicine/2010/press-release/', verifiedAt: '2026-08-31' },
  { id: 'hiv-isolated-identified', prompt: 'When was the virus now known as HIV first isolated and identified?', year: 1983, min: 1900, max: 2020, difficulty: 'survey', detail: 'A Pasteur Institute team reported a newly isolated retrovirus in 1983. Work by several groups in 1983–1984 established the virus now called HIV as the cause of AIDS.', source: 'NCBI Bookshelf — Acquired immune deficiency syndrome', sourceUrl: 'https://www.ncbi.nlm.nih.gov/books/NBK27126/', verifiedAt: '2026-08-31' },
  { id: 'first-covid-vaccine-doses', prompt: 'When were the first COVID-19 vaccine doses administered?', year: 2020, min: 1900, max: 2020, difficulty: 'core', detail: 'The first COVID-19 vaccine doses were administered in December 2020, less than a year after the first recognized cases. Some of the vaccines used mRNA technology.', source: 'World Health Organization — A brief history of vaccination', sourceUrl: 'https://www.who.int/news-room/spotlight/history-of-vaccination/a-brief-history-of-vaccination', verifiedAt: '2026-08-31' },
  { id: 'uruk-first-city', prompt: 'Around when had Uruk become the largest city in southern Mesopotamia?', year: -3200, min: -4000, max: -2500, difficulty: 'survey', detail: 'By around 3200 BCE, Uruk was the largest known settlement in southern Mesopotamia and a true city with monumental buildings. Urbanization developed over centuries.', source: 'Metropolitan Museum of Art — Uruk: The First City', sourceUrl: 'https://www.metmuseum.org/de/essays/uruk-the-first-city', verifiedAt: '2026-08-31' },
  { id: 'mature-harappan-cities', prompt: 'Around when did the mature urban phase of the Indus civilization begin?', year: -2600, min: -3300, max: -1800, difficulty: 'survey', detail: 'The mature Harappan urban phase is conventionally dated to about 2600–1900 BCE, when cities including Mohenjo-daro and Harappa flourished.', source: 'Metropolitan Museum of Art — South Asia, 8000–2000 BCE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/02/ssa.html', verifiedAt: '2026-08-31' },
  { id: 'shang-dynasty', prompt: 'Around when did the Shang dynasty begin?', year: -1600, min: -2200, max: -1000, difficulty: 'survey', detail: 'The archaeologically documented Shang dynasty is conventionally dated to about 1600–1046 BCE. Earlier dynastic traditions remain harder to verify archaeologically.', source: 'Metropolitan Museum of Art — Shang and Zhou Dynasties', sourceUrl: 'https://www.metmuseum.org/pt/essays/shang-and-zhou-dynasties-the-bronze-age-of-china', verifiedAt: '2026-08-31' },
  { id: 'chavin-culture', prompt: 'Around when did the Chavín culture begin in the Peruvian Andes?', year: -1500, min: -2200, max: -500, difficulty: 'specialist', detail: 'UNESCO dates the Chavín culture to roughly 1500–300 BCE. Its highland ceremonial center influenced a wide region, but the period boundaries remain approximate.', source: 'UNESCO World Heritage Centre — Chavín archaeological site', sourceUrl: 'https://whc.unesco.org/en/list/330', verifiedAt: '2026-08-31' },
  { id: 'zhou-conquest', prompt: 'Around when did the Zhou dynasty replace the Shang?', year: -1046, min: -1500, max: -600, difficulty: 'survey', detail: 'The Zhou conquest of the Shang is conventionally dated to 1046 BCE. The Western Zhou then exercised authority over much of central China.', source: 'Metropolitan Museum of Art — Shang and Zhou Dynasties', sourceUrl: 'https://www.metmuseum.org/pt/essays/shang-and-zhou-dynasties-the-bronze-age-of-china', verifiedAt: '2026-08-31' },
  { id: 'han-dynasty-begins', prompt: 'When did the Han dynasty begin?', year: -206, min: -500, max: 100, difficulty: 'core', detail: 'The Han dynasty established rule in 206 BCE after the collapse of the Qin and ensuing civil war. A brief interregnum later divided Western and Eastern Han periods.', source: 'Metropolitan Museum of Art — Age of Empires exhibition', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2017/age-of-empires/exhibition-galleries', verifiedAt: '2026-08-31' },
  { id: 'yijing-srivijaya', prompt: 'When did the pilgrim Yijing first record arriving in Śrīvijaya?', year: 671, min: 400, max: 900, difficulty: 'specialist', detail: 'The Chinese Buddhist pilgrim Yijing described reaching Śrīvijaya in 671. Local Old Malay inscriptions from the 680s provide further evidence for the maritime power.', source: 'Metropolitan Museum of Art — Lost Kingdoms', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Lost_Kingdoms_Hindu_Buddhist_Sculpture_of_Early_Southeast_Asia.pdf', verifiedAt: '2026-08-31' },
  { id: 'khmer-empire-802', prompt: 'When is the beginning of the Khmer Empire conventionally dated?', year: 802, min: 550, max: 1100, difficulty: 'survey', detail: 'An inscription associates Jayavarman II with a declaration of independence at Mahendraparvata in 802 CE, the conventional beginning of the Angkor-era Khmer Empire.', source: 'UNESCO World Heritage Centre — Phnom Kulen', sourceUrl: 'https://whc.unesco.org/fr/listesindicatives/6460/', verifiedAt: '2026-08-31' },
  { id: 'great-zimbabwe-building', prompt: 'Around when did major building begin at Great Zimbabwe?', year: 1100, min: 800, max: 1400, difficulty: 'survey', detail: 'UNESCO dates the surviving built complex broadly to 1100–1450 CE and describes an eleventh-century foundation. The city later became the center of a major Shona state.', source: 'UNESCO World Heritage Centre — Great Zimbabwe', sourceUrl: 'https://whc.unesco.org/en/list/364/', verifiedAt: '2026-08-31' },
  { id: 'tenochtitlan-founded', prompt: 'When was Tenochtitlan founded?', year: 1325, min: 1050, max: 1550, difficulty: 'core', detail: 'Tenochtitlan was founded in 1325 on an island in Lake Texcoco. It became the principal capital of the Mexica-led Triple Alliance in the fifteenth century.', source: 'Smithsonian Institution — The Death of Aztec Tenochtitlan', sourceUrl: 'https://www.si.edu/object/siris_sil_1055918', verifiedAt: '2026-08-31' },
  { id: 'lanse-aux-meadows', prompt: 'Around when did Norse voyagers establish L’Anse aux Meadows?', year: 1000, min: 700, max: 1300, difficulty: 'survey', detail: 'The Newfoundland site preserves an eleventh-century Norse settlement and the earliest confirmed European presence in North America. Indigenous peoples had lived in the region much earlier.', source: 'UNESCO World Heritage Centre — L’Anse aux Meadows', sourceUrl: 'https://whc.unesco.org/en/list/4/', verifiedAt: '2026-08-31' },
  { id: 'maori-settlement-aotearoa', prompt: 'Around when did Polynesian voyagers settle Aotearoa New Zealand?', year: 1275, min: 900, max: 1550, difficulty: 'survey', detail: 'Current evidence places the first lasting arrivals from East Polynesia between about 1250 and 1300 CE. The game uses 1275 as a midpoint, not an exact founding year.', source: 'Te Ara Encyclopedia of New Zealand — Māori arrival and settlement', sourceUrl: 'https://teara.govt.nz/en/history/page-1', verifiedAt: '2026-08-31' },
  { id: 'zheng-he-first-voyage', prompt: 'When did Zheng He depart on his first Indian Ocean voyage?', year: 1405, min: 1150, max: 1650, difficulty: 'survey', detail: 'The Yongle emperor sent Zheng He on the first of seven major maritime expeditions in 1405. The fleets connected Ming China with ports across the Indian Ocean.', source: 'Library of Congress — Voyages of Zheng He', sourceUrl: 'https://tile.loc.gov/storage-services/master/gdc/gdcebookspublic/20/20/71/93/50/2020719350/2020719350.pdf', verifiedAt: '2026-08-31' },
  { id: 'dias-cape-good-hope', prompt: 'When did Bartolomeu Dias round the Cape of Good Hope?', year: 1488, min: 1250, max: 1750, difficulty: 'survey', detail: 'Dias rounded southern Africa in 1488, demonstrating an Atlantic route into the Indian Ocean. His voyage preceded Vasco da Gama’s arrival in India by a decade.', source: 'Library of Congress — Portuguese India chronology', sourceUrl: 'https://tile.loc.gov/storage-services/service/gdc/gdclccn/a2/20/00/97/2/a22000972/a22000972.pdf', verifiedAt: '2026-08-31' },
  { id: 'vasco-da-gama-calicut', prompt: 'When did Vasco da Gama reach Calicut by sea?', year: 1498, min: 1250, max: 1750, difficulty: 'core', detail: 'Da Gama’s fleet reached Calicut on India’s Malabar Coast in May 1498 after sailing around Africa. Existing African and Indian Ocean pilots and trade networks made the crossing possible.', source: 'Library of Congress — Portuguese India chronology', sourceUrl: 'https://tile.loc.gov/storage-services/service/gdc/gdclccn/a2/20/00/97/2/a22000972/a22000972.pdf', verifiedAt: '2026-08-31' },
  { id: 'first-circumnavigation-complete', prompt: 'When did the first circumnavigation of Earth finish?', year: 1522, min: 1300, max: 1800, difficulty: 'core', detail: 'One ship from Magellan’s expedition returned to Spain in 1522 under Juan Sebastián Elcano, completing the first recorded circumnavigation. Magellan had died in 1521.', source: 'Library of Congress — Sailing the Early Seas with Portolan Charts', sourceUrl: 'https://blogs.loc.gov/maps/2019/09/sailing-the-early-seas-with-portolan-charts/', verifiedAt: '2026-08-31' },
  { id: 'manila-galleon-route', prompt: 'When did the Manila–Acapulco galleon trade begin?', year: 1565, min: 1350, max: 1850, difficulty: 'specialist', detail: 'Regular trans-Pacific galleon voyages began in 1565 and continued until 1815, carrying Asian goods eastward and American silver westward.', source: 'Smithsonian Libraries and Archives — The Manila Galleon', sourceUrl: 'https://www.si.edu/object/manila-galleon-william-lytle-schurz%3Asiris_sil_207127', verifiedAt: '2026-08-31' },
  { id: 'voc-founded', prompt: 'When was the Dutch East India Company founded?', year: 1602, min: 1400, max: 1900, difficulty: 'survey', detail: 'The Dutch Republic combined several competing trading companies into the Verenigde Oostindische Compagnie, or VOC, in 1602.', source: 'Rijksmuseum — East Indiamen off the coast', sourceUrl: 'https://www.rijksmuseum.nl/nl/collectie/object/Oost-Indievaarders-voor-de-kust--cb27a8dd65ec584d17acd8579e064ca4', verifiedAt: '2026-08-31' },
  { id: 'tasman-pacific-voyage', prompt: 'When did Abel Tasman reach Tasmania and New Zealand?', year: 1642, min: 1400, max: 1900, difficulty: 'specialist', detail: 'Tasman’s 1642–1643 VOC voyage charted parts of Tasmania and New Zealand before continuing through the Pacific to Tonga and Fiji.', source: 'Royal Museums Greenwich — Exploration and discovery guide', sourceUrl: 'https://www.rmg.co.uk/collections/research-guides/research-guide-q1-exploration-discovery', verifiedAt: '2026-08-31' },
  { id: 'cook-first-pacific-voyage', prompt: 'When did James Cook’s first Pacific voyage begin?', year: 1768, min: 1500, max: 1950, difficulty: 'survey', detail: 'Cook’s Endeavour voyage ran from 1768 to 1771. It observed the transit of Venus and charted New Zealand and the east coast of Australia for Britain.', source: 'Royal Museums Greenwich — Exploration and discovery guide', sourceUrl: 'https://www.rmg.co.uk/collections/research-guides/research-guide-q1-exploration-discovery', verifiedAt: '2026-08-31' },
  { id: 'english-bill-of-rights', prompt: 'When did England enact the Bill of Rights?', year: 1689, min: 1450, max: 1900, difficulty: 'survey', detail: 'Parliament enacted the Bill of Rights in December 1689 after William and Mary accepted the earlier Declaration of Rights. Its guarantees were historically specific, not a universal declaration.', source: 'UK Parliament — The Convention and Bill of Rights', sourceUrl: 'https://www.parliament.uk/about/living-heritage/evolutionofparliament/parliamentaryauthority/revolution/overview/billofrights/', verifiedAt: '2026-08-31' },
  { id: 'us-declaration-independence', prompt: 'When did the Continental Congress adopt the Declaration of Independence?', year: 1776, min: 1550, max: 1950, difficulty: 'core', detail: 'Congress voted for independence on 2 July 1776 and adopted the Declaration’s text on 4 July. Delegates began signing the engrossed parchment in August.', source: 'U.S. National Archives — Declaration of Independence', sourceUrl: 'https://www.archives.gov/milestone-documents/declaration-of-independence', verifiedAt: '2026-08-31' },
  { id: 'haitian-revolution-begins', prompt: 'When did the Haitian Revolution begin?', year: 1791, min: 1550, max: 1950, difficulty: 'survey', detail: 'A mass uprising by enslaved people began in Saint-Domingue in August 1791. Thirteen years of conflict culminated in Haiti’s independence in 1804.', source: 'Library of Congress — Haïti collections guide', sourceUrl: 'https://guides.loc.gov/francophone-caribbean-collections-library-of-congress/haiti', verifiedAt: '2026-08-31' },
  { id: 'mexican-independence-uprising', prompt: 'When did Mexico’s war for independence begin?', year: 1810, min: 1600, max: 2000, difficulty: 'survey', detail: 'Miguel Hidalgo issued the Cry of Dolores on 16 September 1810, conventionally opening the independence struggle. Mexico secured independence after another decade of war.', source: 'Library of Congress — Independence from Spain', sourceUrl: 'https://www.loc.gov/exhibits/mexican-revolution-and-the-united-states/independence-from-spain.html', verifiedAt: '2026-08-31' },
  { id: 'brazil-independence', prompt: 'When did Brazil declare independence from Portugal?', year: 1822, min: 1600, max: 2000, difficulty: 'survey', detail: 'Prince Dom Pedro proclaimed Brazil’s independence on 7 September 1822 and became emperor. Portugal formally recognized the separation in 1825.', source: 'Library of Congress — Empire of Brazil', sourceUrl: 'https://guides.loc.gov/brazil-us-relations/empire-of-brazil', verifiedAt: '2026-08-31' },
  { id: 'british-slavery-abolition-act', prompt: 'When did Parliament pass the Slavery Abolition Act?', year: 1833, min: 1600, max: 2000, difficulty: 'specialist', detail: 'The 1833 Act took effect in 1834 across most British colonies, compensating enslavers and imposing an apprenticeship system. Complete emancipation followed in 1838.', source: 'UK Parliament — Britain and the Transatlantic Slave Trade', sourceUrl: 'https://researchbriefings.files.parliament.uk/documents/LLN-2019-0104/LLN-2019-0104.pdf', verifiedAt: '2026-08-31' },
  { id: 'bolshevik-revolution', prompt: 'When did the Bolsheviks overthrow Russia’s Provisional Government?', year: 1917, min: 1750, max: 2020, difficulty: 'core', detail: 'Bolshevik-aligned forces seized key sites in Petrograd on 7–8 November 1917, corresponding to 25–26 October in the calendar then used in Russia.', source: 'Library of Congress — Russian Revolution and Civil War', sourceUrl: 'https://tile.loc.gov/storage-services/master/gmd/gmd7/g7001/g7001s/2017588308.pdf', verifiedAt: '2026-08-31' },
  { id: 'ghana-independence', prompt: 'When did Ghana gain independence from Britain?', year: 1957, min: 1800, max: 2020, difficulty: 'survey', detail: 'The former Gold Coast became independent Ghana on 6 March 1957 under Prime Minister Kwame Nkrumah. It became a republic three years later.', source: 'Library of Congress — Ghana’s policy at home and abroad', sourceUrl: 'https://www.loc.gov/resource/amed.2008700222/?st=gallery', verifiedAt: '2026-08-31' },
  { id: 'bangladesh-independence-war', prompt: 'When did Bangladesh’s war of independence take place?', year: 1971, min: 1850, max: 2020, difficulty: 'survey', detail: 'The Bangladesh Liberation War began after the Pakistani army’s March 1971 crackdown and ended with surrender on 16 December. Its violence and death toll remain subjects of historical study.', source: 'UK National Archives — Independence of Bangladesh', sourceUrl: 'https://www.nationalarchives.gov.uk/education/resources/the-independence-of-bangladesh-in-1971/', verifiedAt: '2026-08-31' },
  { id: 'south-africa-democratic-election', prompt: 'When did South Africa hold its first nonracial democratic election?', year: 1994, min: 1850, max: 2020, difficulty: 'core', detail: 'South Africans voted on a common electoral roll on 27 April 1994, ending apartheid-era national elections and producing a government of national unity led by Nelson Mandela.', source: 'South African Government — Milestones of freedom', sourceUrl: 'https://www.gov.za/issues/20years/milestones-20-years-freedom', verifiedAt: '2026-08-31' },
  { id: 'league-of-nations-begins', prompt: 'When did the League of Nations come into existence?', year: 1920, min: 1750, max: 2020, difficulty: 'survey', detail: 'The League’s Covenant entered into force in January 1920 after the Treaty of Versailles. The organization pursued collective security but lacked universal membership and effective enforcement.', source: 'United Nations — Predecessor: the League of Nations', sourceUrl: 'https://www.un.org/en/about-us/history-of-the-un/predecessor', verifiedAt: '2026-08-31' },
  { id: 'un-charter-signed', prompt: 'When was the United Nations Charter signed?', year: 1945, min: 1800, max: 2020, difficulty: 'core', detail: 'Representatives of fifty countries signed the Charter in San Francisco on 26 June 1945. It entered into force on 24 October after the required ratifications.', source: 'United Nations — UN Charter', sourceUrl: 'https://www.un.org/en/about-us/un-charter', verifiedAt: '2026-08-31' },
  { id: 'udhr-adopted', prompt: 'When did the UN adopt the Universal Declaration of Human Rights?', year: 1948, min: 1800, max: 2020, difficulty: 'core', detail: 'The General Assembly adopted the declaration in Paris on 10 December 1948 by a vote of 48–0 with eight abstentions. It is a declaration, not itself a binding treaty.', source: 'United Nations — Universal Declaration of Human Rights', sourceUrl: 'https://www.un.org/en/about-us/universal-declaration-of-human-rights/', verifiedAt: '2026-08-31' },
  { id: 'korean-armistice', prompt: 'When was the Korean Armistice signed?', year: 1953, min: 1850, max: 2020, difficulty: 'survey', detail: 'Military commanders signed the armistice at Panmunjom on 27 July 1953, suspending open hostilities and establishing the demilitarized zone. It was not a peace treaty.', source: 'U.S. National Archives — Korean Armistice Agreement', sourceUrl: 'https://www.archives.gov/milestone-documents/armistice-agreement-restoration-south-korean-state', verifiedAt: '2026-08-31' },
  { id: 'bandung-conference', prompt: 'When did the Asian-African Conference meet in Bandung?', year: 1955, min: 1850, max: 2020, difficulty: 'specialist', detail: 'Twenty-nine Asian and African countries met in Bandung, Indonesia, from 18 to 24 April 1955 to advance cooperation, peace, and freedom from colonialism.', source: 'UNESCO Memory of the World — Asian-African Conference Archives', sourceUrl: 'https://www.unesco.org/en/memory-world/asian-african-conference-archives', verifiedAt: '2026-08-31' },
  { id: 'treaties-of-rome', prompt: 'When were the Treaties of Rome signed?', year: 1957, min: 1850, max: 2020, difficulty: 'survey', detail: 'Six states signed treaties establishing the European Economic Community and Euratom on 25 March 1957. Both entered into force at the start of 1958.', source: 'European Parliament — Treaty of Rome', sourceUrl: 'https://www.europarl.europa.eu/about-parliament/en/in-the-past/the-parliament-and-the-treaties/treaty-of-rome', verifiedAt: '2026-08-31' },
  { id: 'cuban-missile-crisis', prompt: 'When did the Cuban Missile Crisis occur?', year: 1962, min: 1850, max: 2020, difficulty: 'core', detail: 'The thirteen-day confrontation began after President Kennedy was briefed on Soviet missile sites in Cuba on 16 October 1962. Negotiations defused the immediate nuclear danger.', source: 'John F. Kennedy Presidential Library — Cuban Missile Crisis', sourceUrl: 'https://microsites.jfklibrary.org/cmc/', verifiedAt: '2026-08-31' },
  { id: 'maastricht-treaty-signed', prompt: 'When was the Maastricht Treaty signed?', year: 1992, min: 1900, max: 2020, difficulty: 'survey', detail: 'Twelve member states signed the Treaty on European Union on 7 February 1992. It entered into force in 1993 and established the European Union and EU citizenship.', source: 'European Parliament — Maastricht Treaty', sourceUrl: 'https://www.europarl.europa.eu/about-parliament/en/in-the-past/the-parliament-and-the-treaties/maastricht-treaty', verifiedAt: '2026-08-31' },
  { id: 'african-union-launched', prompt: 'When was the African Union officially launched?', year: 2002, min: 1900, max: 2020, difficulty: 'survey', detail: 'African leaders launched the African Union in Durban in July 2002 as the successor to the Organisation of African Unity, shifting emphasis toward continental integration.', source: 'African Union — About the African Union', sourceUrl: 'https://www.au.int/en/overview', verifiedAt: '2026-08-31' },
  { id: 'paris-agreement-adopted', prompt: 'When was the Paris climate agreement adopted?', year: 2015, min: 1900, max: 2020, difficulty: 'core', detail: 'Parties adopted the Paris Agreement at COP21 on 12 December 2015. The climate treaty entered into force in November 2016 after crossing its ratification threshold.', source: 'UNFCCC — The Paris Agreement', sourceUrl: 'https://www.unfccc.int/process-and-meetings/the-paris-agreement', verifiedAt: '2026-08-31' },
  { id: 'bank-of-england-founded', prompt: 'When was the Bank of England founded?', year: 1694, min: 1450, max: 1900, difficulty: 'survey', detail: 'A royal charter established the Bank on 27 July 1694, initially as a private bank that lent to the government and helped finance war against France.', source: 'Bank of England — History', sourceUrl: 'https://www.bankofengland.co.uk/about/history?level=1', verifiedAt: '2026-08-31' },
  { id: 'bretton-woods-conference', prompt: 'When did the Bretton Woods conference design a new monetary order?', year: 1944, min: 1800, max: 2020, difficulty: 'survey', detail: 'Delegates from forty-four Allied countries met in New Hampshire in July 1944 and agreed on the institutional plans that produced the IMF and World Bank.', source: 'International Monetary Fund — IMF timeline', sourceUrl: 'https://www.imf.org/external/about/timeline/index.htm', verifiedAt: '2026-08-31' },
  { id: 'imf-begins-operations', prompt: 'When did the International Monetary Fund begin operations?', year: 1947, min: 1800, max: 2020, difficulty: 'specialist', detail: 'The IMF began operations in March 1947 after its Articles of Agreement entered into force and its first member governments established the institution.', source: 'International Monetary Fund — IMF timeline', sourceUrl: 'https://www.imf.org/external/about/timeline/index.htm', verifiedAt: '2026-08-31' },
  { id: 'world-bank-first-loan', prompt: 'When did the World Bank sign its first loan?', year: 1947, min: 1800, max: 2020, difficulty: 'specialist', detail: 'The Bank signed a $250 million reconstruction loan to France on 9 May 1947. In real terms it remains among the largest single loans in the institution’s history.', source: 'World Bank Archives — First loan', sourceUrl: 'https://www.worldbank.org/en/archive/history/exhibits/Digitized-Records-World-Bank-First-Loan', verifiedAt: '2026-08-31' },
  { id: 'gatt-signed', prompt: 'When was the original General Agreement on Tariffs and Trade signed?', year: 1947, min: 1800, max: 2020, difficulty: 'specialist', detail: 'Twenty-three governments signed GATT on 30 October 1947, and provisional application began in 1948. It governed multilateral trade before the WTO.', source: 'World Trade Organization — The GATT years', sourceUrl: 'https://www.wto.org/english/thewto_e/whatis_e/tif_e/fact4_e.htm', verifiedAt: '2026-08-31' },
  { id: 'opec-founded', prompt: 'When was OPEC founded?', year: 1960, min: 1850, max: 2020, difficulty: 'survey', detail: 'Iran, Iraq, Kuwait, Saudi Arabia, and Venezuela created the organization at a Baghdad conference held from 10 to 14 September 1960.', source: 'Organization of the Petroleum Exporting Countries — OPEC turns 61', sourceUrl: 'https://www.opec.org/pr-detail/206-14-sep-2021.html', verifiedAt: '2026-08-31' },
  { id: 'us-gold-window-closed', prompt: 'When did the United States end dollar convertibility into gold?', year: 1971, min: 1850, max: 2020, difficulty: 'survey', detail: 'President Nixon closed the U.S. gold window on 15 August 1971 amid inflation and pressure on reserves, initiating the end of the Bretton Woods fixed-rate system.', source: 'Federal Reserve History — Gold convertibility ends', sourceUrl: 'https://www.federalreservehistory.org/essays/gold-convertibility-ends', verifiedAt: '2026-08-31' },
  { id: 'wto-begins', prompt: 'When did the World Trade Organization begin?', year: 1995, min: 1900, max: 2020, difficulty: 'core', detail: 'The WTO came into existence on 1 January 1995 after the Uruguay Round and the Marrakesh Agreement, succeeding the older GATT institutional framework.', source: 'World Trade Organization — 25 years of the WTO', sourceUrl: 'https://www.wto.org/english/thewto_e/25y_e/25ytimeline_e.htm', verifiedAt: '2026-08-31' },
  { id: 'euro-launched', prompt: 'When was the euro launched as a currency?', year: 1999, min: 1900, max: 2020, difficulty: 'survey', detail: 'The euro began on 1 January 1999 for accounting and electronic payments. Euro banknotes and coins entered circulation three years later, in 2002.', source: 'European Central Bank — Our money', sourceUrl: 'https://www.ecb.europa.eu/euro/intro/html/index.en.html', verifiedAt: '2026-08-31' },
  { id: 'china-joins-wto', prompt: 'When did China join the World Trade Organization?', year: 2001, min: 1900, max: 2020, difficulty: 'core', detail: 'China became a WTO member on 11 December 2001 after a long accession negotiation and acceptance of extensive market-access and trade-policy commitments.', source: 'World Trade Organization — China member information', sourceUrl: 'https://www.wto.org/english/thewto_e/countries_e/china_e.htm', verifiedAt: '2026-08-31' },
  { id: 'stonehenge-central-stones', prompt: 'Around when were Stonehenge’s central stone settings raised?', year: -2500, min: -3200, max: -1800, difficulty: 'core', detail: 'English Heritage dates the raising of Stonehenge’s central sarsen and bluestone settings to about 2500 BCE. An earlier earthwork enclosure had been built around 3000 BCE.', source: 'English Heritage — Building Stonehenge', sourceUrl: 'https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/building-stonehenge/', verifiedAt: '2026-08-31' },
  { id: 'caral-organized-system', prompt: 'Around when did Caral-Supe form an organized regional social system?', year: -2600, min: -3200, max: -1800, difficulty: 'survey', detail: 'UNESCO’s evaluation says Supe Valley settlements were occupied by 3000 BCE but became an organized social system with a capital zone around 2600 BCE. The date remains archaeological and approximate.', source: 'UNESCO World Heritage Centre — Caral-Supe evaluation', sourceUrl: 'https://whc.unesco.org/document/152221', verifiedAt: '2026-08-31' },
  { id: 'meroe-royal-residence', prompt: 'Around when did Meroe become Kush’s principal royal residence?', year: -300, min: -700, max: 100, difficulty: 'survey', detail: 'UNESCO says Meroe became the principal residence of Kushite rulers from the third century BCE onward. This uses 300 BCE as a rough century-level anchor, not an exact transition year.', source: 'UNESCO World Heritage Centre — Archaeological Sites of Meroe', sourceUrl: 'https://whc.unesco.org/en/list/1336/', verifiedAt: '2026-08-31' },
  { id: 'jenne-jeno-first-occupation', prompt: 'Around when was Jenne-jeno first populated?', year: -250, min: -600, max: 200, difficulty: 'specialist', detail: 'The Met reports that Jenne-jeno in today’s Mali was populated as early as 250 BCE and grew into a major urban center by 850 CE. Earliest occupation is necessarily approximate.', source: 'Metropolitan Museum of Art — Inland Niger Delta', sourceUrl: 'https://www.metmuseum.org/essays/inland-niger-delta', verifiedAt: '2026-08-31' },
  { id: 'roman-empire-maximum-trajan', prompt: 'When did the Roman Empire reach its greatest territorial extent under Trajan?', year: 117, min: -50, max: 350, difficulty: 'core', detail: 'The Met identifies Rome’s greatest extent with Trajan’s reign, which ended in 117 CE, when the empire stretched from Britain to Mesopotamia. Borders changed again under Hadrian.', source: 'Metropolitan Museum of Art — Masterpieces of the Met', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Masterpieces_of_the_Metropolitan_Museum_of_Art_2006.pdf', verifiedAt: '2026-08-31' },
  { id: 'justinian-law-compilation', prompt: 'When did Justinian’s great compilation of Roman law begin to appear?', year: 529, min: 300, max: 750, difficulty: 'survey', detail: 'The Library of Congress dates the works later called the Corpus Iuris Civilis to 529–534 CE. This question uses 529 for the beginning of publication, not completion of the whole compilation.', source: 'Library of Congress — Law, Old & New', sourceUrl: 'https://www.loc.gov/loc/lcib/11078/law.html', verifiedAt: '2026-08-31' },
  { id: 'sui-reunification', prompt: 'When did the Sui dynasty reunify China?', year: 589, min: 350, max: 800, difficulty: 'core', detail: 'The Smithsonian National Museum of Asian Art dates the end of China’s long Period of Division to Sui reunification in 589 CE. The Sui dynasty itself had begun in 581.', source: 'Smithsonian National Museum of Asian Art — Period of Division', sourceUrl: 'https://smarthistory.org/period-of-division-intro/', verifiedAt: '2026-08-31' },
  { id: 'goryeo-reunification', prompt: 'When did Wang Geon reunify Korea under the Goryeo dynasty?', year: 918, min: 650, max: 1150, difficulty: 'specialist', detail: 'The Met chronology dates Wang Geon’s reunification under the new Goryeo dynasty to 918 CE. Goryeo endured until 1392 and gave rise to the modern name Korea.', source: 'Metropolitan Museum of Art — Korea, 500–1000 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/06/eak.html', verifiedAt: '2026-08-31' },
  { id: 'monte-alban-founded', prompt: 'Around when was Monte Albán founded?', year: -500, min: -800, max: -200, difficulty: 'survey', detail: 'The Met dates Monte Albán’s founding on its Oaxaca hilltop to about 500 BCE. The Zapotec center then grew for centuries and dominated the surrounding valley.', source: 'Metropolitan Museum of Art — Monte Albán', sourceUrl: 'https://www.metmuseum.org/essays/monte-alban', verifiedAt: '2026-08-31' },
  { id: 'chaco-great-houses', prompt: 'Around when did construction of Chaco Canyon’s great houses begin?', year: 850, min: 600, max: 1200, difficulty: 'survey', detail: 'The U.S. National Park Service dates the beginning of major great-house construction at Pueblo Bonito, Una Vida, and Peñasco Blanco to the middle and late 800s CE. This uses 850 as a rough anchor.', source: 'U.S. National Park Service — Chaco Culture', sourceUrl: 'https://home.nps.gov/articles/chaco.htm', verifiedAt: '2026-08-31' },
  { id: 'nara-permanent-capital', prompt: 'When did Nara become Japan’s first permanent capital?', year: 710, min: 500, max: 950, difficulty: 'survey', detail: 'Japan’s imperial headquarters moved from Asuka to Heijō-kyō at present-day Nara in 710 CE. The grid-planned city was modeled on Tang China’s capital, Chang’an.', source: 'Metropolitan Museum of Art — Japan, 500–1000 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/06/eaj.html', verifiedAt: '2026-08-31' },
  { id: 'umayyad-landing-iberia', prompt: 'When did an Umayyad army land on the Iberian Peninsula?', year: 711, min: 500, max: 950, difficulty: 'core', detail: 'An army of Arabs and Berbers serving the Umayyad caliphate landed on 19 July 711. Over the following years, diplomacy and warfare brought most of Iberia under Muslim rule.', source: 'Metropolitan Museum of Art — Umayyad Spain', sourceUrl: 'https://www.metmuseum.org/de/essays/the-art-of-the-umayyad-period-in-spain-711-1031', verifiedAt: '2026-08-31' },
  { id: 'abbasid-overthrow-umayyads', prompt: 'When did the Abbasids overthrow the Umayyad caliphate?', year: 750, min: 500, max: 950, difficulty: 'survey', detail: 'The Abbasids displaced the Damascus-based Umayyad dynasty in 750 CE. One Umayyad survivor later established a separate emirate in al-Andalus, so Umayyad rule did not vanish everywhere.', source: 'Metropolitan Museum of Art — Umayyad Spain', sourceUrl: 'https://www.metmuseum.org/pt/essays/the-art-of-the-umayyad-period-in-spain-711-1031', verifiedAt: '2026-08-31' },
  { id: 'an-lushan-rebellion-begins', prompt: 'When did the An Lushan rebellion begin?', year: 755, min: 500, max: 950, difficulty: 'survey', detail: 'General An Lushan began his rebellion against the Tang court in December 755. The conflict continued until 763 and permanently weakened Tang central authority.', source: 'Smithsonian National Museum of Asian Art — Shipwrecked', sourceUrl: 'https://asia.si.edu/wp-content/uploads/2023/06/shipwrecked-04-krahl.pdf', verifiedAt: '2026-08-31' },
  { id: 'northern-song-begins', prompt: 'When did the Northern Song dynasty begin?', year: 960, min: 700, max: 1200, difficulty: 'core', detail: 'The Northern Song period began in 960 CE and lasted until 1127. The wider Song dynasty continued in southern China until 1279 after the northern capital was lost.', source: 'Metropolitan Museum of Art — Northern Song Dynasty', sourceUrl: 'https://www.metmuseum.org/ko/essays/northern-song-dynasty-960-1127', verifiedAt: '2026-08-31' },
  { id: 'chichen-itza-maya-toltec-phase', prompt: 'Around when did Chichen Itza’s Maya-Toltec phase begin?', year: 967, min: 700, max: 1200, difficulty: 'specialist', detail: 'UNESCO notes a traditional account placing a Toltec takeover between 967 and 987 CE. This uses the opening of that disputed window, not a securely dated single conquest.', source: 'UNESCO World Heritage Centre — Chichen-Itza', sourceUrl: 'https://whc.unesco.org/en/list/483/', verifiedAt: '2026-08-31' },
  { id: 'cairo-founded-fatimid-capital', prompt: 'When was Cairo founded as the Fatimid capital?', year: 969, min: 700, max: 1200, difficulty: 'survey', detail: 'The Fatimids founded Cairo in 969 CE as the headquarters of their caliphate. The urban center expanded across earlier settlements and later became a major Islamic capital.', source: 'UNESCO World Heritage Centre — Historic Cairo', sourceUrl: 'https://whc.unesco.org/en/list/89', verifiedAt: '2026-08-31' },
  { id: 'angkor-wat-building-phase', prompt: 'When did the great Angkor Wat building phase begin?', year: 1113, min: 850, max: 1350, difficulty: 'specialist', detail: 'UNESCO’s evaluation links a new monumental building phase to Suryavarman II’s accession in 1113 CE. He commissioned Angkor Wat, while construction continued across his reign.', source: 'UNESCO World Heritage Centre — Angkor evaluation', sourceUrl: 'https://whc.unesco.org/archive/advisory_body_evaluation/668.pdf', verifiedAt: '2026-08-31' },
  { id: 'lalibela-reign-begins', prompt: 'Around when did King Lalibela’s church-building era begin?', year: 1181, min: 850, max: 1350, difficulty: 'survey', detail: 'UNESCO dates King Lalibela’s reign to 1181–1221 and attributes eleven rock-hewn churches to him. The 1181 answer anchors a broader building era, not an exact construction start.', source: 'UNESCO World Heritage Centre — Lalibela churches', sourceUrl: 'https://whc.unesco.org/en/activities/160/', verifiedAt: '2026-08-31' },
  { id: 'saladin-retakes-jerusalem', prompt: 'When did Saladin’s forces retake Jerusalem?', year: 1187, min: 850, max: 1350, difficulty: 'core', detail: 'Forces led by Salah al-Din, known in Europe as Saladin, retook Jerusalem in October 1187. The city changed hands again in later decades, so this was not a permanent settlement.', source: 'Metropolitan Museum of Art — The Crusades', sourceUrl: 'https://www.metmuseum.org/ko/essays/the-crusades-1095-1291', verifiedAt: '2026-08-31' },
  { id: 'moche-urban-centers', prompt: 'Around when did the Moche begin building major urban centers?', year: 100, min: -100, max: 400, difficulty: 'survey', detail: 'The Met places the beginning of Moche urban-center construction on Peru’s north coast around 100 CE, including the Huaca del Sol and Huaca de la Luna. The date is approximate.', source: 'Metropolitan Museum of Art — Central and Southern Andes, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/sac.html', verifiedAt: '2026-08-31' },
  { id: 'cai-lun-paper-report', prompt: 'When did Cai Lun report his improved papermaking method?', year: 105, min: -100, max: 400, difficulty: 'survey', detail: 'Chinese tradition dates Cai Lun’s report of an improved bark-, hemp-, rag-, and net-based papermaking method to 105 CE. Archaeological paper predates him, so he was not paper’s literal inventor.', source: 'Hunan Provincial Government — Cai Lun', sourceUrl: 'https://www.enghunan.gov.cn/hneng/AboutHunan/HistoryCulture/Celebrities/201806/t20180619_5035364.html', verifiedAt: '2026-08-31' },
  { id: 'antonine-plague-begins', prompt: 'When did the Antonine plague begin?', year: 165, min: -100, max: 400, difficulty: 'core', detail: 'The epidemic began in Mesopotamia in late 165 or early 166 CE during Rome’s Parthian campaign and spread through the empire. Its pathogen remains debated rather than securely identified.', source: 'National Library of Medicine — The Antonine plague', sourceUrl: 'https://pubmed.ncbi.nlm.nih.gov/17195627/', verifiedAt: '2026-08-31' },
  { id: 'yellow-turban-uprising', prompt: 'When did the Yellow Turban uprising begin?', year: 184, min: -100, max: 400, difficulty: 'survey', detail: 'Zhang Jiao’s religious movement launched a widespread uprising against Eastern Han rule in 184 CE. Government forces suppressed its main armies, but the conflict accelerated political fragmentation.', source: 'National Museum of China — The Yellow Turbans Uprising', sourceUrl: 'https://en.chnmuseum.cn/Portals/0/web/exhibition/exhibitions/161120Chines-Epic/en.html', verifiedAt: '2026-08-31' },
  { id: 'han-dynasty-ends', prompt: 'When did the Han dynasty end?', year: 220, min: 1, max: 500, difficulty: 'core', detail: 'The Eastern Han dynasty ended in 220 CE, after which China divided into the Three Kingdoms. The Han political and cultural legacy long outlasted the dynasty itself.', source: 'Metropolitan Museum of Art — Han Dynasty', sourceUrl: 'https://www.metmuseum.org/TOAH/hd/hand/hd_hand.htm', verifiedAt: '2026-08-31' },
  { id: 'sasanian-empire-begins', prompt: 'Around when did the Sasanian Empire begin?', year: 224, min: 1, max: 500, difficulty: 'survey', detail: 'Around 224 CE, Ardashir I defeated the Parthians and founded the Sasanian dynasty. The empire became Rome and Byzantium’s principal eastern rival for more than four centuries.', source: 'Metropolitan Museum of Art — The Sasanian Empire', sourceUrl: 'https://www.metmuseum.org/ja/essays/the-sasanian-empire-224-651-a-d', verifiedAt: '2026-08-31' },
  { id: 'tikal-first-lowland-long-count', prompt: 'When was the first known Maya Long Count date carved in the lowlands?', year: 292, min: 1, max: 550, difficulty: 'specialist', detail: 'Tikal Stela 29 records a Long Count date corresponding to 8 July 292 CE, the earliest known such date in the Maya lowlands. Earlier Maya writing and calendrical traditions existed.', source: 'Metropolitan Museum of Art — Maya Area, 1–500 CE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/05/caa.html', verifiedAt: '2026-08-31' },
  { id: 'edict-of-milan', prompt: 'When did the Edict of Milan establish tolerance for Christianity?', year: 313, min: 50, max: 600, difficulty: 'core', detail: 'The agreement associated with Constantine and Licinius in 313 CE established religious toleration for Christianity within the Roman Empire. It did not immediately make Christianity the state religion.', source: 'Metropolitan Museum of Art — The Arts of Byzantium', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Arts_of_Byzantium_The_Metropolitan_Museum_of_Art_Bulletin_v_58_no_4_Spring_2001.pdf', verifiedAt: '2026-08-31' },
  { id: 'ezana-converts-aksum', prompt: 'Around when did King Ezana make Aksum a Christian state?', year: 330, min: 50, max: 600, difficulty: 'survey', detail: 'The Met dates Ezana’s conversion to around 330 CE, making Aksum one of the earliest Christian states. Crosses replaced earlier religious symbols on royal coinage.', source: 'Metropolitan Museum of Art — Monumental Architecture of Aksum', sourceUrl: 'https://www.metmuseum.org/fr/essays/monumental-architecture-and-stelae-of-the-aksumite-empire', verifiedAt: '2026-08-31' },
  { id: 'visigoth-sack-rome', prompt: 'When did Alaric’s Visigoths sack Rome?', year: 410, min: 150, max: 700, difficulty: 'core', detail: 'Alaric’s Visigothic army entered and sacked Rome in 410 CE. The shock damaged Roman prestige, although the western imperial government continued for another sixty-six years.', source: 'Metropolitan Museum of Art — The Arts of Byzantium', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Arts_of_Byzantium_The_Metropolitan_Museum_of_Art_Bulletin_v_58_no_4_Spring_2001.pdf', verifiedAt: '2026-08-31' },
  { id: 'proto-cuneiform-writing', prompt: 'Around when did proto-cuneiform writing emerge in Mesopotamia?', year: -3200, min: -3600, max: -2700, difficulty: 'survey', detail: 'The Met dates the earliest stage of proto-cuneiform at Uruk to roughly 3200–3000 BCE. The signs began as administrative pictographs and only gradually developed into a fully phonetic writing system.', source: 'Metropolitan Museum of Art — The Origins of Writing', sourceUrl: 'https://www.metmuseum.org/es/essays/the-origins-of-writing', verifiedAt: '2026-09-01' },
  { id: 'great-pyramid-khufu', prompt: 'Around when did construction of Khufu’s Great Pyramid begin?', year: -2550, min: -2900, max: -2200, difficulty: 'core', detail: 'Khufu commissioned the Great Pyramid during a reign the Smithsonian dates to about 2551–2528 BCE. The game uses 2550 BCE as a memorable reign-level anchor, not a precise construction-start year.', source: 'Smithsonian Institution — The Egyptian Pyramid', sourceUrl: 'https://www.si.edu/spotlight/ancient-egypt/pyramid', verifiedAt: '2026-09-01' },
  { id: 'akkadian-empire-sargon', prompt: 'Around when did Sargon establish the Akkadian Empire?', year: -2350, min: -2700, max: -2000, difficulty: 'survey', detail: 'The Met places Sargon’s reign around 2340–2285 BCE and the Akkadian period around 2350–2150 BCE. This uses 2350 BCE as an approximate anchor for a conquest-built empire, not an exact founding day.', source: 'Metropolitan Museum of Art — The Akkadian Period', sourceUrl: 'https://www.metmuseum.org/de/essays/the-akkadian-period-ca-2350-2150-b-c', verifiedAt: '2026-09-01' },
  { id: 'battle-of-kadesh', prompt: 'When was the Battle of Kadesh fought?', year: -1274, min: -1600, max: -950, difficulty: 'core', detail: 'Egyptian forces under Ramesses II fought the Hittite empire at Kadesh in 1274 BCE. Egyptian records claimed victory, but the battle’s result was inconclusive and both powers endured.', source: 'British Museum — Looking for the Trojan War', sourceUrl: 'https://www.britishmuseum.org/sites/default/files/2019-12/Large%20print%20guide_Troy.pdf', verifiedAt: '2026-09-01' },
  { id: 'greek-adopts-phoenician-alphabet', prompt: 'By around when had Greeks adapted the Phoenician alphabet?', year: -750, min: -1050, max: -500, difficulty: 'survey', detail: 'The Met says Greek speakers adapted the Phoenician alphabet sometime before 750 BCE, including changes that marked vowels. The answer is therefore a useful latest-bound anchor, not a single invention date.', source: 'Metropolitan Museum of Art — Assyria to Iberia', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Assyria_to_Iberia_Art_and_Culture_in_the_Iron_Age.pdf', verifiedAt: '2026-09-01' },
  { id: 'ashoka-reign-begins', prompt: 'Around when did Ashoka’s reign begin?', year: -273, min: -500, max: -100, difficulty: 'survey', detail: 'The Met dates Ashoka’s Mauryan reign to about 273–232 BCE. His later promotion of Buddhist principles and stone inscriptions made that reign historically consequential, but did not begin on one securely dated day.', source: 'Metropolitan Museum of Art — The Year One', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Year_One_Art_of_the_Ancient_World_East_and_West.pdf', verifiedAt: '2026-09-01' },
  { id: 'julius-caesar-assassinated', prompt: 'When was Julius Caesar assassinated?', year: -44, min: -200, max: 100, difficulty: 'core', detail: 'A group of senators assassinated Julius Caesar on 15 March 44 BCE after he became dictator for life. His death did not restore stable republican rule; further civil wars followed.', source: 'Metropolitan Museum of Art — The Roman Republic', sourceUrl: 'https://www.metmuseum.org/de/essays/the-roman-republic', verifiedAt: '2026-09-01' },
  { id: 'teutoburg-forest-battle', prompt: 'When did Germanic forces destroy Varus’s legions?', year: 9, min: -100, max: 150, difficulty: 'core', detail: 'In 9 CE, an alliance led by Arminius ambushed and destroyed three Roman legions commanded by Publius Quinctilius Varus. The event checked Roman expansion east of the Rhine, though later campaigns continued.', source: 'Encyclopaedia Britannica — Battle of the Teutoburg Forest', sourceUrl: 'https://www.britannica.com/event/Battle-of-the-Teutoburg-Forest', verifiedAt: '2026-09-01' },
  { id: 'jesus-crucifixion', prompt: 'Around when was Jesus crucified?', year: 30, min: 1, max: 100, difficulty: 'core', detail: 'A common scholarly estimate places the crucifixion around 30 CE, but the surviving evidence does not securely recover an exact date. The cited study supports a cautious historical range of 29–34 CE.', source: 'Cambridge University Press — Dating the Death of Jesus', sourceUrl: 'https://www.cambridge.org/core/journals/new-testament-studies/article/dating-the-death-of-jesus-memory-and-the-religious-imagination/0458FC0CA55BEF810BCC411AC2765860', verifiedAt: '2026-09-01' },
  { id: 'second-temple-destroyed', prompt: 'When did Roman forces destroy Jerusalem’s Second Temple?', year: 70, min: -50, max: 200, difficulty: 'core', detail: 'Titus’s Roman forces sacked Jerusalem and destroyed the Second Temple in 70 CE during the First Roman–Jewish War. Resistance continued elsewhere until 73, so 70 was not the war’s endpoint.', source: 'Metropolitan Museum of Art — The World between Empires', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_World_between_Empires_Art_and_Identity_in_the_Ancient_Middle_East.pdf', verifiedAt: '2026-09-01' },
  { id: 'council-of-chalcedon', prompt: 'When did the Council of Chalcedon promulgate its creed?', year: 451, min: 250, max: 700, difficulty: 'survey', detail: 'The Fourth Ecumenical Council met at Chalcedon in 451 CE and issued a definition about Christ’s divine and human natures. Its formula did not end the dispute and contributed to lasting church divisions.', source: 'Metropolitan Museum of Art — Age of Spirituality', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Age_of_Spirituality_A_Symposium.pdf', verifiedAt: '2026-09-01' },
  { id: 'hagia-sophia-inaugurated', prompt: 'When was Justinian’s Hagia Sophia inaugurated?', year: 537, min: 300, max: 750, difficulty: 'core', detail: 'Justinian’s new Hagia Sophia was inaugurated in Constantinople on 27 December 537 CE after roughly five years of construction. Earthquakes later required major repairs, including reconstruction of the dome.', source: 'Metropolitan Museum of Art — Hagia Sophia, 532–37', sourceUrl: 'https://www.metmuseum.org/de/essays/hagia-sophia-532-37', verifiedAt: '2026-09-01' },
  { id: 'justinianic-plague-begins', prompt: 'When did the first plague pandemic enter the historical record?', year: 541, min: 300, max: 750, difficulty: 'survey', detail: 'Historical evidence places the first outbreak of the Justinianic plague at Pelusium in 541 CE, and ancient DNA confirms Yersinia pestis in the wider pandemic. Its total mortality and political impact remain disputed.', source: 'Proceedings of the National Academy of Sciences — Justinianic Plague', sourceUrl: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6589673/', verifiedAt: '2026-09-01' },
  { id: 'buddhism-recorded-japan', prompt: 'When was Buddhism’s arrival at Japan’s court first recorded?', year: 552, min: 300, max: 800, difficulty: 'survey', detail: 'A traditional court chronicle dates an embassy from the Korean kingdom of Baekje bearing Buddhist texts and images to 552 CE. Other chronologies use 538, so this is a recorded conventional date, not a first contact.', source: 'Metropolitan Museum of Art — Japanese Art from the Gerry Collection', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Japanese_Art_from_the_Gerry_Collection_in_The_Metropolitan_Museum_of_Art.pdf', verifiedAt: '2026-09-01' },
  { id: 'sasanian-empire-ends', prompt: 'When did the last Sasanian emperor die?', year: 651, min: 450, max: 850, difficulty: 'survey', detail: 'Yazdegerd III, the last Sasanian emperor, died in 651 CE after Arab armies had conquered the empire’s core territories. Sasanian artistic and administrative traditions continued under early Islamic rule.', source: 'Metropolitan Museum of Art — The Sasanians', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2012/byzantium-and-islam/blog/topical-essays/posts/sasanians', verifiedAt: '2026-09-01' },
  { id: 'diamond-sutra-printed', prompt: 'When was the earliest complete dated printed book made?', year: 868, min: 650, max: 1100, difficulty: 'core', detail: 'The surviving Chinese Diamond Sutra was woodblock printed on 11 May 868 CE, according to its colophon. Earlier printing existed, so its distinction is the earliest complete printed book carrying a date.', source: 'British Library International Dunhuang Programme — Diamond Sutra', sourceUrl: 'https://idp.bl.uk/discover/learning/buddhism-on-the-silk-roads/articles/buddhism-on-the-ground/buddhist-texts-the-diamond-sutra/', verifiedAt: '2026-09-01' },
  { id: 'chola-raids-srivijaya', prompt: 'When did the Chola kingdom raid Srivijaya?', year: 1025, min: 800, max: 1250, difficulty: 'specialist', detail: 'The Met chronology dates the Chola kingdom’s naval raids on Srivijaya to 1025 CE. The campaign disrupted a major Southeast Asian maritime power but did not erase its commercial and cultural legacy overnight.', source: 'Metropolitan Museum of Art — Southeast Asia, 1000–1400', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/07/sse.html', verifiedAt: '2026-09-01' },
  { id: 'great-schism-1054', prompt: 'When did the confrontation known as the Great Schism occur?', year: 1054, min: 800, max: 1250, difficulty: 'core', detail: 'In 1054 CE, representatives of Rome and Constantinople exchanged anathemas in a confrontation later treated as the Great Schism. Eastern–western separation was a long process, not a clean one-day break.', source: 'Metropolitan Museum of Art — The Arts of Byzantium', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Arts_of_Byzantium_The_Metropolitan_Museum_of_Art_Bulletin_v_58_no_4_Spring_2001.pdf', verifiedAt: '2026-09-01' },
  { id: 'mongols-sack-baghdad', prompt: 'When did Mongol forces sack Baghdad?', year: 1258, min: 1050, max: 1450, difficulty: 'core', detail: 'Hülegü’s Mongol army captured and devastated Baghdad in 1258 CE, killing the last Abbasid caliph to rule there. Abbasid descendants later held nominal caliphal status in Mamluk Cairo.', source: 'Metropolitan Museum of Art — Iraq, 1000–1400', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/07/wam.html', verifiedAt: '2026-09-01' },
  { id: 'mansa-musa-hajj', prompt: 'When did Mansa Musa make his famous pilgrimage to Mecca?', year: 1324, min: 1100, max: 1500, difficulty: 'core', detail: 'Mansa Musa left Mali on his hajj in 1324 CE and traveled through Cairo to Mecca. The journey advertised Mali’s wealth and connected the empire more visibly to wider Islamic scholarly and commercial networks.', source: 'Metropolitan Museum of Art — Sahel: Art and Empires', sourceUrl: 'https://www.metmuseum.org/de/exhibitions/sahel-art-empire-sahara/inside-the-exhibition', verifiedAt: '2026-09-01' },
  { id: 'luther-ninety-five-theses', prompt: 'When did Martin Luther circulate the Ninety-Five Theses?', year: 1517, min: 1350, max: 1700, difficulty: 'core', detail: 'Luther circulated his Latin theses against indulgence practices in 1517 CE, intending an academic dispute. Printers rapidly reproduced them; the familiar church-door scene is a later tradition rather than the only evidence of circulation.', source: 'Library of Congress — Ninety-Five Theses', sourceUrl: 'https://www.loc.gov/item/2021667736/', verifiedAt: '2026-09-01' },
  { id: 'tenochtitlan-falls', prompt: 'When did the siege of Tenochtitlan end?', year: 1521, min: 1350, max: 1700, difficulty: 'core', detail: 'Tenochtitlan fell on 13 August 1521 after a ninety-three-day siege by Spanish forces and large Indigenous allied armies, especially Tlaxcalans. Smallpox, starvation, disrupted water, and civil conflict were also decisive.', source: 'Metropolitan Museum of Art — Mexico, 1400–1600', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/08/canm.html', verifiedAt: '2026-09-01' },
  { id: 'first-battle-panipat-mughal', prompt: 'When did Babur win the First Battle of Panipat?', year: 1526, min: 1350, max: 1700, difficulty: 'core', detail: 'Babur defeated Ibrahim Lodi at Panipat in 1526 CE, inaugurating Mughal dynastic rule in northern India. Mughal control was interrupted from 1540 to 1555, so the empire did not expand in one uninterrupted line.', source: 'Metropolitan Museum of Art — South Asia, 1400–1600', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/08/ssa.html', verifiedAt: '2026-09-01' },
  { id: 'atahualpa-captured-cajamarca', prompt: 'When did Pizarro’s force capture Atahualpa at Cajamarca?', year: 1532, min: 1350, max: 1700, difficulty: 'core', detail: 'A small Spanish force ambushed and captured Inca ruler Atahualpa at Cajamarca in 1532 CE amid a recent Inca succession war. The capture was decisive, but conquest remained a prolonged campaign shaped by Indigenous alliances and epidemic disease.', source: 'Metropolitan Museum of Art — Central and Southern Andes, 1400–1600', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/08/sanc.html', verifiedAt: '2026-09-01' },
  { id: 'copernicus-de-revolutionibus', prompt: 'When was Copernicus’s De revolutionibus published?', year: 1543, min: 1350, max: 1750, difficulty: 'core', detail: 'Copernicus’s De revolutionibus orbium coelestium appeared in Nuremberg in 1543 CE, shortly before his death. It presented a mathematical heliocentric model that became foundational to later work by Kepler, Galileo, and Newton.', source: 'Library of Congress — A Heliocentric Cosmos', sourceUrl: 'https://www.loc.gov/item/92516339/', verifiedAt: '2026-09-01' },
  { id: 'potosi-silver-exploitation', prompt: 'Around when did colonial silver exploitation begin at Potosí?', year: 1545, min: 1350, max: 1750, difficulty: 'survey', detail: 'Colonial records date exploitation of Cerro Rico’s silver lodes to 1545 CE. “Discovery” here names the start of Spanish extraction, not an empty or unknown landscape; later production transformed global trade and depended heavily on coerced Indigenous labor.', source: 'UNESCO World Heritage Centre — Santa Bárbara mining complex', sourceUrl: 'https://whc.unesco.org/en/tentativelists/6263/', verifiedAt: '2026-09-01' },
  { id: 'council-of-trent-opens', prompt: 'When did the Council of Trent first convene?', year: 1545, min: 1350, max: 1750, difficulty: 'survey', detail: 'The Council of Trent opened in 1545 CE to address Catholic reform and the Protestant challenge. Its sessions occurred intermittently through 1563, so 1545 marks the opening rather than a single-year settlement.', source: 'Metropolitan Museum of Art — Venice and Northern Italy, 1400–1600', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/08/eustn.html', verifiedAt: '2026-09-01' },
  { id: 'battle-of-lepanto', prompt: 'When was the Battle of Lepanto?', year: 1571, min: 1400, max: 1750, difficulty: 'survey', detail: 'A Holy League fleet defeated the Ottoman fleet at Lepanto in October 1571 CE. The battle was a major naval and symbolic victory, but it neither ended Ottoman maritime power nor permanently settled Mediterranean rivalry.', source: 'Metropolitan Museum of Art — North of the Apennines', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/North_of_the_Apennines_Sixteenth_Century_Italian_Painting_in_Venice_and_the_Veneto_The_Metropolitan_Museum_of_Art_Bulletin_v_63_no_1_Summer_2005.pdf', verifiedAt: '2026-09-01' },
  { id: 'gregorian-calendar-reform', prompt: 'When was the Gregorian calendar reform proclaimed?', year: 1582, min: 1400, max: 1800, difficulty: 'survey', detail: 'Pope Gregory XIII proclaimed the calendar reform in 1582 CE, and early adopters skipped ten dates that October. Adoption spread unevenly across countries and confessions over subsequent centuries.', source: 'Smithsonian National Postal Museum — Gregorian calendar reform', sourceUrl: 'https://postalmuseum.si.edu/object/npm_1984.0014.2712', verifiedAt: '2026-09-01' },
  { id: 'battle-of-tondibi', prompt: 'When did Moroccan forces defeat Songhai at Tondibi?', year: 1591, min: 1400, max: 1800, difficulty: 'survey', detail: 'Moroccan forces equipped with firearms defeated the Songhai army at Tondibi in 1591 CE after internal divisions had weakened the empire. They occupied Gao, Timbuktu, and Jenne, while Songhai resistance continued.', source: 'Metropolitan Museum of Art — Sahel: Art and Empires', sourceUrl: 'https://www.metmuseum.org/de/exhibitions/sahel-art-empire-sahara/inside-the-exhibition', verifiedAt: '2026-09-01' },
  { id: 'battle-of-sekigahara', prompt: 'When was the Battle of Sekigahara?', year: 1600, min: 1450, max: 1750, difficulty: 'core', detail: 'Tokugawa Ieyasu’s coalition defeated its rivals at Sekigahara in 1600 CE, establishing the military dominance behind the Tokugawa shogunate. Ieyasu did not receive the title of shogun until 1603, so battle and regime inauguration are distinct anchors.', source: 'Metropolitan Museum of Art — Japanese Art from the Gerry Collection', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Japanese_Art_from_the_Gerry_Collection_in_The_Metropolitan_Museum_of_Art.pdf', verifiedAt: '2026-09-01' },
  { id: 'jamestown-established', prompt: 'When was Jamestown established?', year: 1607, min: 1450, max: 1750, difficulty: 'core', detail: 'Virginia Company colonists selected Jamestown Island in May 1607 CE, creating the first permanent English settlement in North America. The settlement occupied Powhatan territory and survived through Indigenous trade, conflict, coercion, resupply, and high mortality.', source: 'U.S. National Park Service — A Short History of Jamestown', sourceUrl: 'https://www.nps.gov/jame/learn/historyculture/a-short-history-of-jamestown.htm', verifiedAt: '2026-09-01' },
  { id: 'kepler-astronomia-nova', prompt: 'When was Kepler’s Astronomia nova published?', year: 1609, min: 1450, max: 1750, difficulty: 'survey', detail: 'Johannes Kepler published Astronomia nova in 1609 CE, using Tycho Brahe’s Mars observations to present elliptical planetary orbits and changing orbital speed. The date marks publication of his first two planetary laws, not their instantaneous discovery.', source: 'Smithsonian Libraries — Astronomia nova', sourceUrl: 'https://library.si.edu/digital-library/book/astronomianovaa00kepl', verifiedAt: '2026-09-01' },
  { id: 'galileo-sidereus-nuncius', prompt: 'When did Galileo publish Sidereus Nuncius?', year: 1610, min: 1450, max: 1750, difficulty: 'core', detail: 'Galileo published Sidereus Nuncius, or The Starry Messenger, in March 1610 CE. It reported telescopic observations of the Moon, the Milky Way, and four moons orbiting Jupiter; telescope construction and observation began earlier.', source: 'Library of Congress — Galileo and the Telescope', sourceUrl: 'https://www.loc.gov/collections/finding-our-place-in-the-cosmos-with-carl-sagan-and-beyond/articles-and-essays/modeling-the-cosmos/galileo-and-the-telescope', verifiedAt: '2026-09-01' },
  { id: 'first-documented-africans-virginia', prompt: 'When were the first documented Africans brought to English Virginia?', year: 1619, min: 1450, max: 1800, difficulty: 'core', detail: 'In August 1619 CE, an English privateer brought captive Africans taken from a Spanish slave ship to Point Comfort, Virginia. This is the first documented African arrival in English Virginia—not the beginning of African presence or the slave trade in the Americas—and their immediate legal status remains debated.', source: 'U.S. National Park Service — Arrival of the First Africans in 1619', sourceUrl: 'https://home.nps.gov/articles/000/arrival-of-the-first-africans-in-1619.htm', verifiedAt: '2026-09-01' },
  { id: 'taj-mahal-construction-begins', prompt: 'When did construction of the Taj Mahal begin?', year: 1632, min: 1500, max: 1800, difficulty: 'survey', detail: 'Construction of the Taj Mahal began in Agra in 1632 CE by order of Mughal emperor Shah Jahan after Mumtaz Mahal’s death. The main mausoleum was completed around 1648, while surrounding buildings and gardens continued to about 1653.', source: 'UNESCO World Heritage Centre — Taj Mahal', sourceUrl: 'https://whc.unesco.org/en/list/252/', verifiedAt: '2026-09-01' },
  { id: 'peace-of-westphalia', prompt: 'When was the Peace of Westphalia concluded?', year: 1648, min: 1500, max: 1800, difficulty: 'core', detail: 'The treaties collectively called the Peace of Westphalia were concluded in 1648 CE, ending the Thirty Years’ War and settling parts of the wider European conflict. Later accounts often overstate this as the single birth moment of modern sovereignty.', source: 'United Nations Digital Library — Peace of Westphalia historical record', sourceUrl: 'https://digitallibrary.un.org/record/1480617/files/A_AC.119_SR.30-EN.pdf', verifiedAt: '2026-09-01' },
  { id: 'voc-cape-foothold', prompt: 'When did the VOC establish its foothold at the Cape?', year: 1652, min: 1500, max: 1800, difficulty: 'survey', detail: 'Jan van Riebeeck’s VOC expedition reached Table Bay in April 1652 CE to establish a refreshment station. It became a permanent settler foothold through land grants, imported enslaved labor, territorial expansion, and conflict with Khoikhoi communities; those later developments were not completed in one year.', source: 'South African History Online — Arrival of Jan van Riebeeck', sourceUrl: 'https://sahistory.org.za/article/arrival-jan-van-riebeeck-cape-6-april-1652', verifiedAt: '2026-09-01' },
  { id: 'hooke-micrographia', prompt: 'When was Robert Hooke’s Micrographia published?', year: 1665, min: 1500, max: 1800, difficulty: 'survey', detail: 'Robert Hooke’s Micrographia appeared in London in 1665 CE under the Royal Society’s imprimatur. Its detailed microscope observations and images helped make previously invisible structures publicly legible; microscopy itself predated the book.', source: 'Royal Society — Micrographia title page', sourceUrl: 'https://pictures.royalsociety.org/image-rs-6108', verifiedAt: '2026-09-01' },
  { id: 'newton-principia', prompt: 'When was Newton’s Principia published?', year: 1687, min: 1500, max: 1850, difficulty: 'core', detail: 'Isaac Newton’s Philosophiae Naturalis Principia Mathematica was published in 1687 CE after Edmond Halley helped bring the manuscript through the press. It systematized laws of motion and universal gravitation; the underlying work developed over preceding decades.', source: 'Royal Society — The Principia manuscript', sourceUrl: 'https://royalsociety.org/news/2014/astronaut-tim-peake-principia/', verifiedAt: '2026-09-01' },
  { id: 'asante-kingdom-forms', prompt: 'Around when did the Asante kingdom form?', year: 1700, min: 1500, max: 1850, difficulty: 'survey', detail: 'The Asante kingdom formed around 1700 CE under Osei Tutu through a confederation of Akan states connected by trade, language, and political institutions. Its territorial expansion continued through the eighteenth century, so this is an approximate formation anchor rather than a single founding day.', source: 'Metropolitan Museum of Art — Art of the Asante Kingdom', sourceUrl: 'https://www.metmuseum.org/fr/essays/art-of-the-asante-kingdom', verifiedAt: '2026-09-01' },
  { id: 'newcomen-atmospheric-engine', prompt: 'Around when did Newcomen introduce a practical atmospheric engine?', year: 1712, min: 1550, max: 1850, difficulty: 'core', detail: 'Thomas Newcomen and John Calley introduced a practical atmospheric pumping engine around 1712 CE. It was an early large-scale reciprocating steam engine used to drain mines; Watt’s later separate condenser improved efficiency rather than inventing steam power from nothing.', source: 'Science Museum Group — Newcomen pumping engine', sourceUrl: 'https://collection.sciencemuseumgroup.org.uk/objects/co50887/drawing-of-thomas-newcomens-pumping-engine-1712-drawing', verifiedAt: '2026-09-01' },
  { id: 'boston-smallpox-variolation', prompt: 'When did Boston carry out its contested smallpox variolation campaign?', year: 1721, min: 1550, max: 1850, difficulty: 'survey', detail: 'During Boston’s 1721 CE smallpox epidemic, Zabdiel Boylston used variolation after Cotton Mather promoted knowledge shared by Onesimus, an enslaved West African man. Variolation had long histories in Africa and Asia and was riskier than Jenner’s later cowpox vaccination.', source: 'Smithsonian NMAAHC — Onesimus and the 1721 Smallpox Outbreak', sourceUrl: 'https://learninglab.si.edu/collections/onesimus-and-the-1721-smallpox-outbreak-in-boston/Ya3HENakRPRLW37a', verifiedAt: '2026-09-01' },
  { id: 'nadir-shah-sacks-delhi', prompt: 'When did Nadir Shah sack Delhi?', year: 1739, min: 1550, max: 1850, difficulty: 'survey', detail: 'Nadir Shah invaded Mughal India and sacked Delhi in 1739 CE, carrying away enormous wealth. The attack exposed Mughal political weakness but did not by itself end the empire, which persisted amid regional fragmentation and new powers.', source: 'Metropolitan Museum of Art — Masterpieces of Islamic Art', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Masterpieces_from_the_Department_of_Islamic_Art_in_The_Metropolitan_Museum_of_Art.pdf', verifiedAt: '2026-09-01' },
  { id: 'seven-years-war-begins', prompt: 'When did the Seven Years’ War begin?', year: 1756, min: 1600, max: 1900, difficulty: 'core', detail: 'The formally named Seven Years’ War ran from 1756 to 1763 CE across Europe, North America, the Caribbean, West Africa, and South Asia. Fighting between British and French interests had already begun in North America in 1754, so 1756 marks expansion into the general war.', source: 'National Army Museum — Seven Years War', sourceUrl: 'https://www.nam.ac.uk/explore/seven-years-war', verifiedAt: '2026-09-01' },
  { id: 'battle-of-plassey', prompt: 'When was the Battle of Plassey?', year: 1757, min: 1600, max: 1900, difficulty: 'core', detail: 'East India Company forces defeated the nawab of Bengal at Plassey in June 1757 CE during the wider Seven Years’ War. Military discipline mattered, but conspiracy and defection within Siraj-ud-Daulah’s command were also central; Company territorial power expanded over later decades.', source: 'National Army Museum — Seven Years War', sourceUrl: 'https://www.nam.ac.uk/explore/seven-years-war', verifiedAt: '2026-09-01' },
  { id: 'us-constitution-signed', prompt: 'When was the U.S. Constitution signed?', year: 1787, min: 1650, max: 1950, difficulty: 'core', detail: 'Thirty-nine delegates signed the U.S. Constitution in Philadelphia on 17 September 1787 CE. Signing did not make it operative: nine state conventions had to ratify it, and the new federal government began functioning in 1789.', source: 'U.S. National Archives — Constitution of the United States', sourceUrl: 'https://www.archives.gov/milestone-documents/constitution', verifiedAt: '2026-09-01' },
  { id: 'first-fleet-sydney-cove', prompt: 'When did the First Fleet establish a convict settlement at Sydney Cove?', year: 1788, min: 1650, max: 1950, difficulty: 'core', detail: 'The First Fleet established a British convict settlement at Sydney Cove in January 1788 CE. This marks the beginning of British colonization there, not the beginning of Australian history; the Eora were the land’s traditional owners and colonization transformed their lives.', source: 'National Museum of Australia — Convict cargo', sourceUrl: 'https://www.nma.gov.au/defining-moments/resources/convict-cargo', verifiedAt: '2026-09-01' },
  { id: 'macartney-embassy-china', prompt: 'When did the Macartney embassy reach the Qianlong emperor?', year: 1793, min: 1650, max: 1950, difficulty: 'survey', detail: 'Lord Macartney’s British embassy met the Qianlong emperor in 1793 CE while seeking diplomatic exchange and wider commercial access. The mission failed to secure new treaty relations; later retellings should not reduce the encounter to a single ritual dispute.', source: 'Metropolitan Museum of Art — Interwoven Globe chronology', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2013/interwoven-globe', verifiedAt: '2026-09-01' },
  { id: 'rosetta-stone-rediscovered', prompt: 'When was the Rosetta Stone rediscovered?', year: 1799, min: 1650, max: 1950, difficulty: 'core', detail: 'French soldiers found the Rosetta Stone reused in fort foundations near Rashid in July 1799 CE. The stela itself was carved in 196 BCE, and its three scripts enabled later decipherment; rediscovery and decipherment are different events.', source: 'British Museum — Explore the Rosetta Stone', sourceUrl: 'https://www.britishmuseum.org/collection/egypt/explore-rosetta-stone', verifiedAt: '2026-09-01' },
  { id: 'upper-lower-egypt-unified', prompt: 'Around when were Upper and Lower Egypt politically unified?', year: -3100, min: -3500, max: -2700, difficulty: 'core', detail: 'The Met places the political unification of Upper and Lower Egypt and the introduction of writing around 3100 BCE. State formation was a process visible across archaeology and later royal traditions, so this is a period anchor rather than a securely dated ceremony.', source: 'Metropolitan Museum of Art — The Art of Ancient Egypt', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Art_of_Ancient_Egypt_A_Resource_for_Educators.pdf', verifiedAt: '2026-09-01' },
  { id: 'minoan-palace-centers', prompt: 'Around when did Minoan palace centers emerge on Crete?', year: -1900, min: -2300, max: -1500, difficulty: 'survey', detail: 'Around 1900 BCE, major Minoan centers such as Knossos, Phaistos, Mallia, and Zakros developed palace complexes concentrating economic, political, artistic, and probably ritual activity. “Palace” describes a complex institution, not simply a royal residence.', source: 'Metropolitan Museum of Art — Minoan Crete', sourceUrl: 'https://www.metmuseum.org/it/essays/minoan-crete', verifiedAt: '2026-09-01' },
  { id: 'egypt-new-kingdom-begins', prompt: 'Around when did Egypt’s New Kingdom begin?', year: -1550, min: -1900, max: -1200, difficulty: 'core', detail: 'Egypt’s New Kingdom is conventionally dated from about 1550 to 1070 BCE, beginning after rulers based at Thebes expelled the Hyksos. Period labels compress contested dynastic transitions, so 1550 BCE is an approximate chronological boundary.', source: 'Metropolitan Museum of Art — The Art of Ancient Egypt', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/The_Art_of_Ancient_Egypt_A_Resource_for_Educators.pdf', verifiedAt: '2026-09-01' },
  { id: 'nok-culture-origins', prompt: 'Around when do current estimates place the origins of Nok culture?', year: -1500, min: -1900, max: -900, difficulty: 'survey', detail: 'Recent research summarized by the Met moves the origins of Nok culture in present-day Nigeria back to around 1500 BCE. Complex terracotta production and advanced iron smelting are evidenced later, so the origin date should not be assigned wholesale to every Nok practice.', source: 'Metropolitan Museum of Art — Arts of Africa', sourceUrl: 'https://www.metmuseum.org/ja/exhibitions/arts-of-africa/inside-the-exhibition', verifiedAt: '2026-09-01' },
  { id: 'late-bronze-age-disruptions', prompt: 'Around when did major Late Bronze Age disruptions hit the eastern Mediterranean?', year: -1200, min: -1500, max: -900, difficulty: 'survey', detail: 'Around the twelfth century BCE, several eastern Mediterranean and Levantine cities were violently destroyed or abandoned while exchange systems changed and iron use spread. Causes and timing differed by region, so “Bronze Age collapse” is not one simultaneous universal event.', source: 'Metropolitan Museum of Art — Eastern Mediterranean and Syria, 2000–1000 BCE', sourceUrl: 'https://82nd-and-fifth.metmuseum.org/toah/ht/03/wae.html', verifiedAt: '2026-09-01' },
  { id: 'lapita-reaches-tonga-samoa', prompt: 'Around when did Lapita voyagers reach Tonga and Samoa?', year: -1000, min: -1400, max: -700, difficulty: 'survey', detail: 'Lapita communities expanding eastward through Melanesia reached Tonga and Samoa by roughly 1000 BCE. The date is archaeological and approximate; later Polynesian cultures developed through additional centuries of local change and voyaging.', source: 'Metropolitan Museum of Art — Lapita Pottery', sourceUrl: 'https://www.metmuseum.org/pt/essays/lapita-pottery-ca-1500-500-b-c', verifiedAt: '2026-09-01' },
  { id: 'sennacherib-western-campaign', prompt: 'When did Sennacherib campaign against revolts in the Levant?', year: -701, min: -900, max: -500, difficulty: 'core', detail: 'Assyrian king Sennacherib campaigned west in 701 BCE against revolts in Phoenicia, Philistia, and Judah. His annals describe tribute from Hezekiah and the confinement of Jerusalem; Assyrian and biblical accounts frame the outcome differently.', source: 'Metropolitan Museum of Art — Sennacherib and Jerusalem', sourceUrl: 'https://www.metmuseum.org/exhibitions/listings/2014/assyria-to-iberia/blog/posts/sennacherib-and-jerusalem', verifiedAt: '2026-09-01' },
  { id: 'kleisthenes-athenian-reforms', prompt: 'When did Kleisthenes introduce reforms foundational to Athenian democracy?', year: -508, min: -700, max: -300, difficulty: 'core', detail: 'Kleisthenes introduced a new Athenian constitution in 508/7 BCE that reorganized citizens into ten tribes and weakened aristocratic family blocs. Participation remained restricted primarily to adult male citizens, excluding most residents by modern democratic standards.', source: 'Metropolitan Museum of Art — Greek Art from Prehistoric to Classical', sourceUrl: 'https://resources.metmuseum.org/resources/metpublications/pdf/Greek_Art_From_Prehistoric_to_Classical.pdf', verifiedAt: '2026-09-01' },
  { id: 'historical-buddha-dies', prompt: 'Around when did the historical Buddha die?', year: -400, min: -650, max: -200, difficulty: 'survey', detail: 'Many current reconstructions place the Buddha’s death and parinirvana around 400 BCE, while older traditional chronologies often use earlier dates. The surviving evidence does not support an exact year, making this a deliberately approximate anchor.', source: 'Metropolitan Museum of Art — Tree and Serpent', sourceUrl: 'https://www.metmuseum.org/de/exhibitions/tree-and-serpent/visiting-guide', verifiedAt: '2026-09-01' },
  { id: 'alexander-crosses-into-asia', prompt: 'When did Alexander cross into Asia to attack the Persian Empire?', year: -334, min: -500, max: -150, difficulty: 'core', detail: 'Alexander led a Macedonian and allied army across the Hellespont into Asia in 334 BCE, beginning the campaign that overthrew the Achaemenid Empire. His conquest depended on years of battles, sieges, logistics, diplomacy, and forces assembled under Philip II.', source: 'Metropolitan Museum of Art — The Rise of Macedon', sourceUrl: 'https://www.metmuseum.org/ja/essays/the-rise-of-macedonia-and-the-conquests-of-alexander-the-great', verifiedAt: '2026-09-01' },
];

export function formatHistoryYear(year: number) {
  if (year < 0) return `${Math.abs(year).toLocaleString()} BCE`;
  if (year > 0) return `${year.toLocaleString()} CE`;
  return 'BCE / CE';
}

export type HistoryEra = 'BCE' | 'CE';

export function parseHistoryGuess(value: string, era: HistoryEra) {
  const trimmed = value.trim();
  if (!/^\d+$/.test(trimmed)) return null;
  const year = Number(trimmed);
  if (!Number.isSafeInteger(year) || year < 1) return null;
  return era === 'BCE' ? -year : year;
}

function hash(value: string) {
  let result = 2166136261;
  for (const character of value) result = Math.imul(result ^ character.charCodeAt(0), 16777619);
  return result >>> 0;
}

export function dailyHistoryDeck(dayKey: string, questions = historyQuestions) {
  return [...questions].sort((left, right) => hash(`${dayKey}:${left.id}`) - hash(`${dayKey}:${right.id}`)).slice(0, Math.min(dailyHistoryQuestionCount, questions.length));
}

export function historyPoints(guess: number, answer: number) {
  const distance = Math.abs(guess - answer);
  if (distance === 0) return 1000;
  if (distance <= 2) return 900;
  if (distance <= 5) return 800;
  if (distance <= 10) return 650;
  if (distance <= 25) return 500;
  if (distance <= 50) return 300;
  if (distance <= 100) return 150;
  return 0;
}

export function historyLevel(scores: number[]) {
  const average = scores.length ? scores.reduce((sum, score) => sum + score, 0) / scores.length : 0;
  if (average >= 900) return { name: 'PhD-level round', note: 'Nearly exact across the whole set.' };
  if (average >= 750) return { name: 'Graduate seminar', note: 'Excellent chronology, including the harder dates.' };
  if (average >= 600) return { name: 'History undergraduate', note: 'Strong command of the broad timeline.' };
  if (average >= 450) return { name: '10th-grade history', note: 'The major eras are in place.' };
  if (average >= 300) return { name: '7th-grade history', note: 'A useful timeline is taking shape.' };
  return { name: '3rd-grade history', note: 'Start with the big anchors and play again tomorrow.' };
}
